// Parse datasets/curator_config.json (fetched as text by DownloadTemplate) into a
// single validated item that every downstream node reads via
// $('parse_curator_config').first().json. Missing keys fall back to defaults, so a
// partial config file can never take the run down.
const raw = $json.output || '{}';
let cfg;
try {
  cfg = JSON.parse(raw);
} catch (e) {
  throw new Error('datasets/curator_config.json is not valid JSON: ' + e.message);
}

const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const bool = (v, d) => (typeof v === 'boolean' ? v : d);
const arr = (v, d) => (Array.isArray(v) ? v : d);
const obj = (v, d) => (v && typeof v === 'object' && !Array.isArray(v) ? v : d);

const sources = obj(cfg.sources, {});
const hnTop = obj(sources.hn_top, {});
const backlog = obj(cfg.backlog, {});

const out = {
  lookback_days: num(cfg.lookback_days, 5),
  max_entries_per_category: num(cfg.max_entries_per_category, 1000),
  min_title_chars: num(cfg.min_title_chars, 15),
  min_content_words: num(cfg.min_content_words, 120),

  max_candidates: num(cfg.max_candidates, 60),
  // Per-category pool share is derived from category_weights in rank_candidates, so
  // there is deliberately no max_per_category knob: a flat ceiling is what let Tech
  // take 20 of 60 slots while Hacker News got 1.
  max_per_host: num(cfg.max_per_host, 3),
  judge_n: num(cfg.judge_n, 24),
  min_postability: num(cfg.min_postability, 4),

  // The queue is a durable backlog drained one row per sharing run, so there is no
  // top_n / max_per_domain / max_per_category_in_top any more: nothing builds a slate
  // of five. Variety is decided on the way out by topic rotation.
  //
  // These fallbacks MUST track the config file. They are what a broken or truncated
  // download degrades to, and a stale fallback is a silent config rollback: the
  // NEWS_REACTION default sat at 4 against a lookback of 5, which is the arithmetic that
  // admitted news rows already past their TTL. Every value here must clear lookback_days
  // plus the longest publish gap for the same reason.
  backlog: {
    max_per_category: num(backlog.max_per_category, 10),
    max_total: num(backlog.max_total, 60),
    ttl_days: obj(backlog.ttl_days, { NEWS_REACTION: 10, HARD_NUMBER: 45, default: 60 }),
  },

  // Only used to warn in the digest when the backlog holds more than the TTL window can
  // ever publish. Nothing gates on it - the publish schedule lives in LinkedIn Post Sharing.
  publish_per_week: Math.max(1, num(cfg.publish_per_week, 3)),

  mark_read: bool(cfg.mark_read, false),
  write_to_sheet: bool(cfg.write_to_sheet, false),
  http_concurrency: Math.max(1, num(cfg.http_concurrency, 6)),

  hn_engagement: bool(cfg.hn_engagement, true),
  hn_hot_points: num(cfg.hn_hot_points, 100),
  hn_boost: num(cfg.hn_boost, 0.1),
  starred_boost: num(cfg.starred_boost, 0.05),

  sources: {
    hn_top: {
      enabled: bool(hnTop.enabled, true),
      min_points: num(hnTop.min_points, 80),
      limit: num(hnTop.limit, 40),
    },
  },

  priority_bands: obj(cfg.priority_bands, { VERY_HIGH: 0.8, HIGH: 0.65, MEDIUM: 0.5 }),
  // default 0 - with three wanted categories, anything else is something new in Miniflux
  // that nobody has weighted yet, and 0 pool slots is the safe reading of "undecided".
  category_weights: obj(cfg.category_weights, { default: 0 }),
  exclude_categories: arr(cfg.exclude_categories, []).map((s) => String(s)),
  aggregator_hosts: arr(cfg.aggregator_hosts, []).map((s) => String(s).toLowerCase()),
  domain_blocklist: arr(cfg.domain_blocklist, []).map((s) => String(s).toLowerCase()),
  title_blocklist: arr(cfg.title_blocklist, []).map((s) => String(s).toLowerCase()),
  shared_keywords: arr(cfg.shared_keywords, []).map((s) => String(s).toLowerCase()),
};

// The keyword list is edited per category - the per-category lists route Hacker News
// candidates, which arrive with no category of their own - and rank_candidates wants one
// flat list for the affinity count. Derive the flat one rather than keeping both in the
// file, so a term added to a category cannot be missing from the affinity vocabulary.
const rawCatKw = obj(cfg.category_keywords, {});
out.category_keywords = {};
for (const cat of Object.keys(rawCatKw)) {
  out.category_keywords[cat] = arr(rawCatKw[cat], []).map((s) => String(s).toLowerCase());
}
out.topic_keywords = [
  ...new Set([...Object.values(out.category_keywords).flat(), ...out.shared_keywords]),
];

const nowMs = Date.now();
out.run_at = new Date(nowMs).toISOString();
out.published_after = Math.floor((nowMs - out.lookback_days * 86400000) / 1000);

return [{ json: out }];

// Every source, one output shape. Downstream nodes read $('fetch_candidates') and
// never care where a candidate came from: same fields, same units, one item each.
//
// Each source is wrapped in its own try/catch. The Algolia API has outages, and that is
// not a reason to skip a run that Miniflux alone could still curate - the failure lands
// in source_errors and is printed in the Slack digest instead of throwing.
//
// Reddit used to be a third source and was removed. top.json 403s unauthenticated
// clients outright; top.rss worked for one run and then started returning 429 for
// subreddit after subreddit even at 7s spacing with the order rotated by day. Across its
// best run it contributed 5 candidates out of 839 and admitted none, for eight requests
// and up to a minute of wall clock. It needs a registered OAuth app to be worth having;
// until then the cost was all error noise.
//
// Miniflux is asked per category rather than once globally: a single query is
// ordered published_at desc and capped, so the highest-volume category eats the
// budget and the oldest part of the window is silently dropped. On the first real
// run 231 of 400 entries were News, which is excluded anyway, leaving ~19 real
// candidates out of a 792-entry window.
const cfg = $('parse_curator_config').first().json;
const nowMs = Date.now();
const sinceSec = cfg.published_after;

const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const hostOf = (u) => {
  try {
    return new URL(String(u)).hostname.replace(/^www\./, '').toLowerCase();
  } catch (e) {
    const m = String(u || '').match(/^[a-z]+:\/\/([^/?#]+)/i);
    return m ? m[1].replace(/^www\./, '').toLowerCase() : '';
  }
};
const stripHtml = (h) =>
  String(h || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
const stripTracking = (x) => {
  x.hash = '';
  x.hostname = x.hostname.replace(/^www\./, '').toLowerCase();
  const drop = [];
  x.searchParams.forEach((_, k) => {
    if (/^(utm_|ref$|ref_src$|source$|mc_cid$|mc_eid$|fbclid$|gclid$|igshid$|_hsenc$|_hsmi$|at_medium$|at_campaign$)/i.test(k)) drop.push(k);
  });
  drop.forEach((k) => x.searchParams.delete(k));
  x.pathname = x.pathname.replace(/\/+$/, '') || '/';
  return x;
};
// Identity for dedupe: no scheme, no tracking params, no trailing slash.
const canonical = (u) => {
  try {
    const x = stripTracking(new URL(String(u).trim()));
    const path = x.pathname === '/' ? '' : x.pathname;
    const qs = x.searchParams.toString();
    return (x.hostname + path + (qs ? '?' + qs : '')).toLowerCase();
  } catch (e) {
    return String(u || '').trim().toLowerCase();
  }
};
// What actually gets stored and published: the real URL minus the RSS tracking
// junk, so "Source here:" in the post is not a utm_source link.
const cleanUrl = (u) => {
  try {
    return stripTracking(new URL(String(u).trim())).toString().replace(/\?$/, '');
  } catch (e) {
    return String(u || '').trim();
  }
};

// One shape to rule them all. votes/comments are whatever the source already told
// us for free - Miniflux has none, so fetch_hn_signal fills those in later.
const candidate = (c) => {
  const text = String(c.text || '');
  const words = text ? text.split(' ').length : 0;
  const pubMs = c.published_at ? new Date(c.published_at).getTime() : NaN;
  return {
    source: c.source,
    entry_id: c.entry_id || '',
    url: cleanUrl(c.url),
    canonical_url: canonical(c.url),
    host: hostOf(c.url),
    title: String(c.title || '').trim(),
    author: c.author || '',
    category: c.category,
    feed_title: c.feed_title || '',
    published_at: c.published_at || null,
    hours_old: isFinite(pubMs) ? Math.max(0, (nowMs - pubMs) / 3600000) : 9999,
    starred: !!c.starred,
    votes: num(c.votes, 0),
    comments: num(c.comments, 0),
    discussion_url: c.discussion_url || '',
    hn_story_url: c.source === 'hn' ? c.discussion_url || '' : '',
    word_count: words,
    thin_content: words < cfg.min_content_words,
    excerpt: text.slice(0, 1200),
    content_text: text.slice(0, 8000),
  };
};

const out = [];
const perSource = {};
const errors = [];
let truncated = false;
const startedAt = Date.now();

// --- Miniflux -------------------------------------------------------------
try {
  const base = String($env.MINIFLUX_URL || '').replace(/\/+$/, '');
  if (!base) throw new Error('MINIFLUX_URL is not set on the n8n pod');
  const auth =
    'Basic ' + Buffer.from(String($env.MINIFLUX_API_USER) + ':' + String($env.MINIFLUX_API_PASSWORD)).toString('base64');
  const get = (url, qs) =>
    this.helpers.httpRequest({ method: 'GET', url, qs, headers: { Authorization: auth }, json: true, timeout: 30000 });

  const categories = await get(base + '/v1/categories', {});
  // Excluded categories are never fetched, so they cost nothing at all - Miniflux
  // has no "not this category" filter.
  const wanted = (Array.isArray(categories) ? categories : []).filter(
    (c) => c && c.title && !cfg.exclude_categories.includes(c.title)
  );

  let got = 0;
  for (const c of wanted) {
    const res = await get(base + '/v1/entries', {
      status: 'unread',
      category_id: c.id,
      order: 'published_at',
      direction: 'desc',
      limit: cfg.max_entries_per_category,
      published_after: sinceSec,
    });
    const entries = Array.isArray(res && res.entries) ? res.entries : [];
    const total = res && typeof res.total === 'number' ? res.total : entries.length;
    if (total > entries.length) {
      truncated = true;
      console.log('WARNING ' + c.title + ' truncated: ' + entries.length + ' of ' + total + ' - raise max_entries_per_category');
    }
    for (const e of entries) {
      out.push(
        candidate({
          source: 'miniflux',
          entry_id: e.id,
          url: e.url,
          title: e.title,
          author: e.author,
          category: (e.feed && e.feed.category && e.feed.category.title) || 'unknown',
          feed_title: (e.feed && e.feed.title) || '',
          published_at: e.published_at,
          starred: e.starred,
          text: stripHtml(e.content),
        })
      );
    }
    got += entries.length;
  }
  perSource.miniflux = got;
} catch (e) {
  perSource.miniflux = 0;
  errors.push('miniflux: ' + String((e && e.message) || e).slice(0, 160));
}

// --- Hacker News top stories ---------------------------------------------
// Not the same thing as fetch_hn_signal. That node asks "how popular is this
// article the feeds gave me"; this one treats the front page as a source in its
// own right, because 68 RSS feeds still miss the engineering writeup nobody
// syndicates. min_points is the whole filter: the crowd already triaged these.
//
// HN candidates are ROUTED into Data/AI/DevOps rather than carrying a category of their
// own. Giving them "HN" was a mistake: that category drew a pool quota of 12 and filled 2,
// because most HN links are correctly merged into the publisher's copy by filter_candidates
// before ranking - which is where HN's value actually is, since only HN knows the vote
// count. The survivors are the unsyndicated writeups the source was added for, so they are
// filed by whichever category's keywords their title matches most. A bare link has no
// excerpt, so the title is all there is; one matching nothing is dropped rather than parked
// in a fourth category, because zero affinity loses the quota race anyway.
const routeHn = (title) => {
  const t = ' ' + String(title || '').toLowerCase().replace(/[^a-z0-9+#]+/g, ' ') + ' ';
  let best = '';
  let bestHits = 0;
  let bestWeight = -1;
  for (const cat of Object.keys(cfg.category_keywords)) {
    if (cfg.exclude_categories.includes(cat)) continue;
    const weight = cfg.category_weights[cat] != null ? cfg.category_weights[cat] : num(cfg.category_weights.default, 0);
    if (weight <= 0) continue;
    let hits = 0;
    for (const term of cfg.category_keywords[cat]) {
      if (t.includes(' ' + term.replace(/[^a-z0-9+#]+/g, ' ') + ' ')) hits++;
    }
    // Ties break toward the heavier category, so a "kubernetes + kafka" title lands in the
    // one you would rather publish from instead of on list order.
    if (hits > bestHits || (hits > 0 && hits === bestHits && weight > bestWeight)) {
      best = cat;
      bestHits = hits;
      bestWeight = weight;
    }
  }
  return best;
};
let hnUnrouted = 0;

if (cfg.sources.hn_top.enabled) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://hn.algolia.com/api/v1/search_by_date',
      qs: {
        tags: 'story',
        numericFilters: 'created_at_i>' + sinceSec + ',points>' + cfg.sources.hn_top.min_points,
        hitsPerPage: cfg.sources.hn_top.limit,
      },
      json: true,
      timeout: 15000,
    });
    let kept = 0;
    for (const h of (res && res.hits) || []) {
      // Ask HN / Tell HN carry no URL, so there is nothing for the post generator
      // to cite or for Download Content to fetch.
      if (!h || !h.url) continue;
      const cat = routeHn(h.title || h.story_title);
      if (!cat) {
        hnUnrouted++;
        continue;
      }
      out.push(
        candidate({
          source: 'hn',
          url: h.url,
          title: h.title || h.story_title,
          author: h.author,
          category: cat,
          feed_title: 'Hacker News front page',
          published_at: h.created_at,
          votes: h.points,
          comments: h.num_comments,
          discussion_url: 'https://news.ycombinator.com/item?id=' + h.objectID,
          text: stripHtml(h.story_text),
        })
      );
      kept++;
    }
    perSource.hn = kept;
  } catch (e) {
    perSource.hn = 0;
    errors.push('hn_top: ' + String((e && e.message) || e).slice(0, 160));
  }
}

const stats = { per_source: perSource, source_errors: errors, truncated, total: out.length, hn_unrouted: hnUnrouted };
console.log('fetch_candidates: ' + out.length + ' raw candidate(s) in ' + (Date.now() - startedAt) + 'ms ' + JSON.stringify(stats));
if (errors.length) console.log('WARNING fetch_candidates source failures: ' + errors.join(' | '));

if (out.length === 0) return [{ json: { empty: true, _fetch_stats: stats } }];
return out.map((c) => ({ json: { ...c, _fetch_stats: stats } }));

// Everything that can be decided for free, decided before a token is spent: the
// blocklists, the sheet dedupe (a URL in either tab has already been through the
// chain, whatever its STATUS), and same-story collapse across sources.
//
// Collapse merges rather than discards. The same article arrives from both the blog's own
// feed and the Hacker News front page, and only Hacker News knows the vote count.
// Dropping the duplicate would throw that away, so the surviving copy inherits the
// highest votes/comments it saw.
// --- shared helpers (duplicated per Code node; n8n has no module scope) -------
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
// Fuzzy title identity. The same announcement gets rewritten by every outlet
// ("cut compaction cost by 40%" vs "reduce compaction costs 40 percent"), so an
// exact fingerprint does not catch syndication - token overlap does. Trailing
// plurals are stripped so cost/costs collapse.
const titleTokens = (t) =>
  new Set(
    String(t || '')
      .toLowerCase()
      .replace(/[^a-z0-9 ]/g, ' ')
      .split(/\s+/)
      // Keep short numeric tokens: they are the version, and dropping them makes
      // "Claude Opus 5" and "Claude Opus 4.6" look like the same story.
      .filter((w) => w.length > 3 || /\d/.test(w))
      .map((w) => w.replace(/s$/, ''))
  );
const jaccard = (a, b) => {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  return inter / (a.size + b.size - inter);
};
const canonicalRow = (u) =>
  String(u || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[?#].*$/, '')
    .replace(/\/+$/, '');
const TITLE_DUP_THRESHOLD = 0.55;

const cfg = $('parse_curator_config').first().json;
const fetched = $('fetch_candidates').all().map((i) => i.json).filter((j) => j && j.url && !j.empty);
const fetchStats = ($('fetch_candidates').first().json || {})._fetch_stats || { per_source: {}, source_errors: [], total: 0 };

// Both tabs: content_queue is the live queue, articles_2_linkedin is frozen
// history. A URL in either one has already been through the chain.
const rows = [...$('read_legacy_sheet').all(), ...$('read_articles_sheet').all()]
  .map((i) => i.json)
  .filter((r) => r && r.URL);
const seenUrls = new Set(rows.map((r) => canonicalRow(r.URL)));
const seenTitleSets = rows.map((r) => titleTokens(r.TITLE)).filter((s) => s.size >= 3);

const isAggregator = (host) => cfg.aggregator_hosts.some((h) => String(host || '').endsWith(h));

// Collapse is first-wins, so this ordering decides which copy of a story survives:
// a real publisher over an aggregator, then whoever arrived first. Votes are merged
// afterwards either way, so nothing is lost by preferring the publisher's copy.
const candidates = fetched
  .slice()
  .sort((a, b) => (isAggregator(a.host) ? 1 : 0) - (isAggregator(b.host) ? 1 : 0) || a.hours_old - b.hours_old);

const stats = {
  total: candidates.length,
  per_source: fetchStats.per_source,
  source_errors: fetchStats.source_errors,
  truncated: !!fetchStats.truncated,
  hn_unrouted: num(fetchStats.hn_unrouted, 0),
  excluded_category: 0,
  no_title: 0,
  seen_in_sheet: 0,
  blocked: 0,
  merged: 0,
  kept: 0,
};

const kept = [];
const keptByUrl = new Map();
const keptTitleSets = [];

for (const c of candidates) {
  if (cfg.exclude_categories.includes(c.category)) {
    stats.excluded_category++;
    continue;
  }
  if (!c.url || c.title.length < cfg.min_title_chars) {
    stats.no_title++;
    continue;
  }
  const tokens = titleTokens(c.title);
  if (
    seenUrls.has(c.canonical_url) ||
    (tokens.size >= 3 && seenTitleSets.some((s) => jaccard(tokens, s) >= TITLE_DUP_THRESHOLD))
  ) {
    stats.seen_in_sheet++;
    continue;
  }
  const lowerTitle = c.title.toLowerCase();
  if (
    cfg.title_blocklist.some((b) => lowerTitle.includes(b)) ||
    cfg.domain_blocklist.some((b) => c.canonical_url.includes(b))
  ) {
    stats.blocked++;
    continue;
  }

  // Same story as something already kept? Merge the crowd signal into it.
  let twin = keptByUrl.get(c.canonical_url) || null;
  if (!twin && tokens.size >= 3) {
    for (const k of kept) {
      if (k._tokens.size >= 3 && jaccard(tokens, k._tokens) >= TITLE_DUP_THRESHOLD) {
        twin = k;
        break;
      }
    }
  }
  if (twin) {
    stats.merged++;
    if (num(c.votes, 0) + num(c.comments, 0) > num(twin.votes, 0) + num(twin.comments, 0)) {
      twin.votes = num(c.votes, 0);
      twin.comments = num(c.comments, 0);
      twin.discussion_url = c.discussion_url || twin.discussion_url;
      if (c.hn_story_url) twin.hn_story_url = c.hn_story_url;
    }
    twin.also_from = [...new Set([...(twin.also_from || []), c.source])];
    // Miniflux is the only source with the full article body, so if the surviving
    // copy is a bare aggregator link and the duplicate has text, take the text.
    if (twin.thin_content && !c.thin_content) {
      twin.excerpt = c.excerpt;
      twin.content_text = c.content_text;
      twin.word_count = c.word_count;
      twin.thin_content = false;
    }
    if (!twin.entry_id && c.entry_id) twin.entry_id = c.entry_id;
    continue;
  }

  const row = { ...c, _tokens: tokens, also_from: [] };
  kept.push(row);
  keptByUrl.set(c.canonical_url, row);
  keptTitleSets.push(tokens);
  stats.kept++;
}

console.log('filter_candidates', JSON.stringify({ ...stats, source_errors: stats.source_errors.length }));
return kept.map((c) => {
  const { _tokens, ...rest } = c;
  return { json: { ...rest, _filter_stats: stats } };
});

// Rank for free, then cap. Only max_candidates candidates go on to the HN
// engagement lookup and only judge_n reach the LLM, so this node decides what the
// expensive stages ever get to see - with no network calls and no tokens.
//
// It replaces the buzz index, which cost ~140 Miniflux count queries per run to
// produce a number that was 0.9 for anything matching the vocabulary and 0.25 for
// anything else. That is not a trend signal, it is topic affinity with extra steps
// and a wall-clock bill - so measure topic affinity directly and keep the money.
//
// The one thing the old pre-rank got right and must not regress: ranking on recency
// alone threw away 204 candidates for being a few hours older than the rest.
const cfg = $('parse_curator_config').first().json;
const items = $input.all().map((i) => i.json).filter((j) => j && j.url);
const stats = (items[0] && items[0]._filter_stats) || { total: 0, kept: 0, per_source: {}, source_errors: [] };

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const escapeRx = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const terms = cfg.topic_keywords.map((t) => ({
  term: t,
  rx: new RegExp('(^|[^a-z0-9+#])' + escapeRx(t) + '([^a-z0-9+#]|$)', 'i'),
}));
// A concrete figure in the headline or opening is the single best free predictor of
// a postable article - it is what the judge's HARD_NUMBER hook needs and what the
// post generator opens with. Bare years are not numbers in that sense.
const NUMBER_RX = /\b\d+(?:[.,]\d+)?\s*(?:%|x\b|ms\b|µs\b|ns\b|s\b|gb\b|tb\b|pb\b|mb\b|kb\b|k\b|m\b|b\b|qps\b|rps\b|req\/s|tokens?\b|cores?\b|nodes?\b|times\b|percent\b|usd\b|\$)|\$\s*\d|\b\d+(?:[.,]\d+)?x\b/i;

const catWeight = (c) =>
  cfg.category_weights[c.category] != null ? cfg.category_weights[c.category] : num(cfg.category_weights.default, 0.8);

const scored = items.map((c) => {
  const title = String(c.title || '');
  const head = (c.excerpt || '').slice(0, 600);
  // Title hits count double: a keyword in the headline is what the article is
  // about, the same keyword in paragraph four is a passing mention.
  let hits = 0;
  const matched = [];
  for (const t of terms) {
    const inTitle = t.rx.test(title);
    const inBody = inTitle ? false : t.rx.test(head);
    if (!inTitle && !inBody) continue;
    hits += inTitle ? 2 : 1;
    matched.push(t.term);
  }
  const affinity = clamp(hits / 4, 0, 1);
  const hasNumber = NUMBER_RX.test(title) || NUMBER_RX.test(head);
  const substance = (hasNumber ? 0.6 : 0) + (c.thin_content ? 0 : 0.4);
  const recency = clamp(1 - c.hours_old / (cfg.lookback_days * 24), 0, 1);
  // Votes are free here: the aggregator sources already handed them over, and
  // filter_candidates merged them onto whichever copy survived. Miniflux-only
  // candidates sit at 0 and make the difference up on affinity - fetch_hn_signal
  // gives them their engagement number a step later.
  const votes = clamp(Math.log10(1 + num(c.votes, 0) + num(c.comments, 0)) / 2.5, 0, 1);

  const prerank = catWeight(c) * (0.45 * affinity + 0.2 * substance + 0.15 * recency + 0.2 * votes);
  return {
    ...c,
    topic_hits: matched.slice(0, 4),
    has_number: hasNumber,
    f_affinity: Math.round(affinity * 1000) / 1000,
    f_substance: substance,
    f_recency: Math.round(recency * 1000) / 1000,
    f_votes: Math.round(votes * 1000) / 1000,
    prerank: Math.round(prerank * 10000) / 10000,
  };
});

const sorted = scored
  .slice()
  .sort((a, b) => b.prerank - a.prerank || a.hours_old - b.hours_old);

// The pool is ALLOCATED, not filled first-come. A flat per-category ceiling gave the
// 60 slots to whichever category happened to have the most entries: Tech took 20 -
// weight 0.65, and the config calls it rarely postable - while Hacker News put 40
// candidates in and got 1 slot, because a bare link has no excerpt to match keywords
// against and so loses to any Miniflux article on affinity. Adding a source is
// pointless if the cap then deletes 39/40 of it.
//
// So each category gets a share of max_candidates proportional to its weight, over
// the categories actually present in this run, and competes only against itself.
// Within a category the thin-content penalty is a constant, so it stops distorting.
const present = [...new Set(items.map((c) => c.category))];
const totalWeight = present.reduce((s, c) => s + Math.max(0, catWeight({ category: c })), 0);
const quotaOf = new Map();
for (const cat of present) {
  const w = Math.max(0, catWeight({ category: cat }));
  // weight 0 means "never postable" (News), which is a zero, not one free slot.
  quotaOf.set(cat, w <= 0 || totalWeight <= 0 ? 0 : Math.max(1, Math.round((cfg.max_candidates * w) / totalWeight)));
}

const byCategory = new Map();
for (const c of sorted) {
  if (!byCategory.has(c.category)) byCategory.set(c.category, []);
  byCategory.get(c.category).push(c);
}

// One publisher took 8 of 60 pool slots on the run that motivated this (cncf.io),
// which is 8 judge calls that could return the same argument eight times. The slate
// already caps hosts; the pool feeding it has to as well or the cap has nothing
// diverse left to choose from.
const takenUrls = new Set();
const hostCount = new Map();
const kept = [];
const take = (list, limit) => {
  let n = 0;
  for (const c of list) {
    if (n >= limit || kept.length >= cfg.max_candidates) break;
    if (takenUrls.has(c.canonical_url)) continue;
    const h = c.host || '(no host)';
    if ((hostCount.get(h) || 0) >= cfg.max_per_host) continue;
    hostCount.set(h, (hostCount.get(h) || 0) + 1);
    takenUrls.add(c.canonical_url);
    kept.push(c);
    n++;
  }
  return n;
};

for (const [cat, list] of byCategory) take(list, quotaOf.get(cat) || 0);

// Unused quota is not wasted, but it is not handed out best-first either. Redistributing
// globally let ONE high-volume low-weight category absorb every spare slot: Hacker News
// could supply only 4 of its 10 (its duplicates are merged into the publisher's copy
// upstream, correctly) and Reddit 7 of 10, and Tech - 300 candidates at weight 0.65 -
// took all 9 leftovers and finished at 16 against a quota of 7. The judge then blocked 9
// of 16 finalists, because consumer tech is exactly what it is there to block. So the
// leftovers are re-allocated by weight over the categories that still have candidates,
// which is the same rule as the first pass, applied again.
const remainingIn = (cat) => (byCategory.get(cat) || []).filter((c) => !takenUrls.has(c.canonical_url)).length;
let guard = 0;
while (kept.length < cfg.max_candidates && guard++ < 20) {
  const hungry = present.filter((c) => catWeight({ category: c }) > 0 && remainingIn(c) > 0);
  if (!hungry.length) break;
  const slots = cfg.max_candidates - kept.length;
  const w = hungry.reduce((s, c) => s + catWeight({ category: c }), 0);
  let progress = 0;
  for (const cat of hungry) {
    if (kept.length >= cfg.max_candidates) break;
    const share = Math.max(1, Math.round((slots * catWeight({ category: cat })) / w));
    progress += take(byCategory.get(cat), share);
  }
  // Every remaining candidate is blocked by the host cap, so more rounds cannot help.
  if (!progress) break;
}

// Always emit one item so if_has_candidates can route an empty run to notify_empty.
if (kept.length === 0) return [{ json: { empty: true, considered: 0, filter_stats: stats } }];

const byCat = {};
for (const c of kept) byCat[c.category] = (byCat[c.category] || 0) + 1;
const quotaByCat = {};
for (const cat of present) quotaByCat[cat] = quotaOf.get(cat) || 0;
const dropped = sorted.length - kept.length;
console.log(
  'rank_candidates: kept ' + kept.length + ' of ' + sorted.length +
    ' | quota ' + JSON.stringify(quotaByCat) + ' | filled ' + JSON.stringify(byCat)
);

return kept.map((c, i) => ({
  json: {
    ...c,
    cid: 'c' + (i + 1),
    empty: false,
    considered: kept.length,
    capped_out: dropped,
    pool_by_category: byCat,
    quota_by_category: quotaByCat,
    filter_stats: stats,
  },
}));

// The one measured signal in the pipeline: how much attention this story is
// actually getting, from Hacker News, free and without a key. Everything else the
// curator knows is either an opinion (the judge) or a heuristic (the pre-rank).
//
// Two passes, because the two questions are different:
//   1. exact URL - "was this page submitted"
//   2. title     - "is this story big anywhere"
// Pass 2 is what actually measures virality. The Claude Opus 5 launch thread points
// at anthropic.com, so a URL lookup on a blog's commentary about it returns 0 hits
// while the title lookup finds 1711 points. URL-only matching scored 0.00 for every
// article across two runs - the engagement signal was dead weight.
//
// Candidates that came from the front page already carry their exact score, so they
// are skipped: with hn_top enabled that is a third of the lookups gone.
// --- shared helpers (duplicated per Code node; n8n has no module scope) -------
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const titleTokens = (t) =>
  new Set(
    String(t || '')
      .toLowerCase()
      .replace(/[^a-z0-9 ]/g, ' ')
      .split(/\s+/)
      .filter((w) => w.length > 3 || /\d/.test(w))
      .map((w) => w.replace(/s$/, ''))
  );
const jaccard = (a, b) => {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  return inter / (a.size + b.size - inter);
};
const canonicalHit = (u) =>
  String(u || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[?#].*$/, '')
    .replace(/\/+$/, '');

const cfg = $('parse_curator_config').first().json;
const items = $input.all().map((i) => i.json);

const settle = (j, points, comments, story, match, error) => ({
  json: {
    ...j,
    hn_points: Math.max(num(points, 0), j.source === 'hn' ? num(j.votes, 0) : 0),
    hn_comments: Math.max(num(comments, 0), j.source === 'hn' ? num(j.comments, 0) : 0),
    hn_story_url: story || j.hn_story_url || '',
    hn_match: match,
    hn_error: error || '',
  },
});

if (!cfg.hn_engagement) {
  return items.map((j) => settle(j, j.votes, j.comments, j.hn_story_url, 'disabled', ''));
}

const search = (qs) =>
  this.helpers.httpRequest({
    method: 'GET',
    url: 'https://hn.algolia.com/api/v1/search',
    qs: { tags: 'story', ...qs },
    json: true,
    timeout: 8000,
  });

// Algolia requires every query token to match by default, so a long headline
// returns nothing. Six significant words is enough to identify a story.
const titleQuery = (t) =>
  String(t || '')
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter((w) => w.length > 2)
    .slice(0, 6)
    .join(' ');

// Small worker pool. These calls are independent, so running them one at a time was
// pure wall clock.
const runPool = async (list, worker, concurrency) => {
  const out = new Array(list.length);
  let next = 0;
  await Promise.all(
    Array.from({ length: Math.max(1, Math.min(concurrency, list.length)) }, async () => {
      for (;;) {
        const i = next++;
        if (i >= list.length) return;
        out[i] = await worker(list[i], i);
      }
    })
  );
  return out;
};

const since = Math.floor(Date.now() / 1000) - 14 * 86400;
const startedAt = Date.now();
let errors = 0;
let matched = 0;
let skipped = 0;

const out = await runPool(
  items,
  async (j) => {
    // Already know the exact number, from the front page itself.
    if (j.hn_story_url && num(j.votes, 0) > 0) {
      skipped++;
      matched++;
      return settle(j, j.votes, j.comments, j.hn_story_url, 'source');
    }
    let points = 0;
    let comments = 0;
    let story = '';
    let match = 'none';
    let error = '';
    const take = (h) => {
      if (num(h.points, 0) + num(h.num_comments, 0) <= points + comments) return;
      points = num(h.points, 0);
      comments = num(h.num_comments, 0);
      story = 'https://news.ycombinator.com/item?id=' + h.objectID;
    };
    try {
      // Pass 1: this exact page.
      const byUrl = await search({ query: j.canonical_url, restrictSearchableAttributes: 'url', hitsPerPage: 5 });
      for (const h of (byUrl && byUrl.hits) || []) {
        if (h && h.url && canonicalHit(h.url) === j.canonical_url) {
          match = 'url';
          take(h);
        }
      }
      // Pass 2: the same story, wherever it was submitted. Guarded by title overlap
      // so a generic query cannot borrow an unrelated thread's points.
      if (match === 'none') {
        const mine = titleTokens(j.title);
        const q = titleQuery(j.title);
        // Short titles ("Brute intelligence") cannot be identified reliably by an OR
        // query - two tokens match half of Hacker News. Skip rather than guess.
        if (mine.size >= 3 && q) {
          const byTitle = await search({
            query: q,
            // Algolia ANDs every token by default, so "introducing claude opus" misses
            // a thread titled "Claude Opus 5". optionalWords makes them OR; the
            // overlap guard below is what keeps the result honest.
            optionalWords: q,
            hitsPerPage: 20,
            numericFilters: 'created_at_i>' + since,
          });
          for (const h of (byTitle && byTitle.hits) || []) {
            if (!h) continue;
            if (jaccard(mine, titleTokens(h.title || h.story_title || '')) < 0.4) continue;
            match = 'title';
            take(h);
          }
        }
      }
    } catch (e) {
      errors++;
      error = String((e && e.message) || e).slice(0, 200);
    }
    if (match !== 'none') matched++;
    return settle(j, points, comments, story, match, error);
  },
  cfg.http_concurrency
);

// Surfaced because a blocked egress rule and "nothing is popular today" look
// identical from the digest otherwise.
console.log(
  'fetch_hn_signal: ' + matched + '/' + out.length + ' matched (' + skipped + ' free from hn_top), ' +
    errors + ' request error(s), ' + (Date.now() - startedAt) + 'ms'
);
return out.map((o) => ({ json: { ...o.json, _hn_matched: matched, _hn_lookups: out.length - skipped, _hn_errors: errors } }));

// Choose who gets judged. One LLM call per finalist reads the full article, so this
// is the last free decision in the run and the only place the judge_n budget is set.
//
// Same-story collapse happens here rather than in an LLM call, because the only
// signal that was ever proof is free: two candidates pointing at the same Hacker
// News thread are the same story. The simonwillison and TechCrunch write-ups of
// Opus 5 both resolved to one 1719pt thread. Title overlap already collapsed in
// filter_candidates; this catches the pairs whose headlines share nothing.
const cfg = $('parse_curator_config').first().json;
const items = $input.all().map((i) => i.json).filter((j) => j && j.cid);

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);

// prerank plus the engagement we have now actually measured. Deliberately not a new
// formula: the pre-rank already weighed the free signals against each other, and
// this only lets a story that turned out to be big on Hacker News overtake one that
// merely looked promising.
const withEngagement = items.map((j) => {
  const engagement = clamp(Math.log10(1 + num(j.hn_points, 0) + num(j.hn_comments, 0)) / 2.5, 0, 1);
  return {
    ...j,
    f_engagement: Math.round(engagement * 1000) / 1000,
    rank_score: Math.round((num(j.prerank, 0) + 0.25 * engagement) * 10000) / 10000,
  };
});

const ranked = withEngagement.sort((a, b) => b.rank_score - a.rank_score || a.hours_old - b.hours_old);

const threads = new Map();
const unique = [];
let collapsed = 0;
for (const j of ranked) {
  const t = j.hn_story_url || '';
  if (t && threads.has(t)) {
    collapsed++;
    continue;
  }
  if (t) threads.set(t, j.cid);
  unique.push(j);
}

// Never judge more than the backlog could possibly accept. A judge call is the only
// expensive thing in the run, and admitting is the only thing it buys - so once the
// backlog is full, judging 24 articles to admit zero is pure waste. Yield has run
// around a quarter, so budget four calls per free slot and let judge_n be the ceiling.
// This is what makes running the curator daily cheap: it is a top-up job, and a topped-up
// backlog costs almost nothing.
const bl = cfg.backlog;
const queuedRows = $('read_articles_sheet')
  .all()
  .map((i) => i.json)
  .filter((r) => r && r.URL && String(r.STATUS || '').trim() === 'QUEUE');

const catWeight = (cat) =>
  cfg.category_weights[cat] != null ? cfg.category_weights[cat] : num(cfg.category_weights.default, 0.8);
const byCategory = new Map();
for (const j of unique) {
  if (!byCategory.has(j.category)) byCategory.set(j.category, []);
  byCategory.get(j.category).push(j);
}
const present = [...byCategory.keys()];

// Room is per category, not just global. max_per_category * 5 categories is 50 against a
// max_total of 60, so the per-category cap is what actually binds - and it binds unevenly:
// a run that admitted 3 AI and 1 DevOps fills AI in three runs while Data sits empty.
// After that, allocating by weight alone hands AI its usual ~5 calls per run and
// admit_to_backlog rejects all five with "AI backlog full". So a full category is not
// hungry, and no category is judged more than four calls deep into the room it has left.
const queuedByCat = new Map();
for (const r of queuedRows) {
  const cat = String(r.TOPIC || '').trim() || 'unknown';
  queuedByCat.set(cat, (queuedByCat.get(cat) || 0) + 1);
}
const roomIn = (cat) => Math.max(0, bl.max_per_category - num(queuedByCat.get(cat), 0));
const roomTotal = Math.max(0, bl.max_total - queuedRows.length);
const roomPresent = present.reduce((s, c) => s + (catWeight(c) > 0 ? roomIn(c) : 0), 0);
const room = Math.min(roomTotal, roomPresent);
const budget = Math.max(0, Math.min(cfg.judge_n, room * 4));

// Allocate the judge's queue by category weight, the same rule rank_candidates uses for
// the pool. A flat per-category cap of judge_n/3 let Tech take a third of the calls, and
// the judge blocks consumer tech on sight - those were 6 calls spent to learn nothing.
const takenCids = new Set();
const finalists = [];
const take = (list, limit) => {
  let n = 0;
  for (const j of list || []) {
    if (n >= limit || finalists.length >= budget) break;
    if (takenCids.has(j.cid)) continue;
    takenCids.add(j.cid);
    finalists.push(j);
    n++;
  }
  return n;
};
const remainingIn = (cat) => (byCategory.get(cat) || []).filter((j) => !takenCids.has(j.cid)).length;
const takenIn = (cat) => (byCategory.get(cat) || []).filter((j) => takenCids.has(j.cid)).length;
let guard = 0;
while (finalists.length < budget && guard++ < 20) {
  const hungry = present.filter((c) => catWeight(c) > 0 && remainingIn(c) > 0 && takenIn(c) < roomIn(c) * 4);
  if (!hungry.length) break;
  const slots = budget - finalists.length;
  const w = hungry.reduce((s, c) => s + catWeight(c), 0);
  let progress = 0;
  for (const cat of hungry) {
    if (finalists.length >= budget) break;
    const byWeight = Math.max(1, Math.round((slots * catWeight(cat)) / w));
    progress += take(byCategory.get(cat), Math.min(byWeight, roomIn(cat) * 4 - takenIn(cat)));
  }
  if (!progress) break;
}
// Best-first overall inside the budget, so the loop judges the strongest ones first.
finalists.sort((a, b) => b.rank_score - a.rank_score || a.hours_old - b.hours_old);

const byCat = {};
const byHost = {};
for (const j of unique) {
  byCat[j.category] = (byCat[j.category] || 0) + 1;
  byHost[j.host || '(no host)'] = (byHost[j.host || '(no host)'] || 0) + 1;
}
const finalistsByCat = {};
for (const j of finalists) finalistsByCat[j.category] = (finalistsByCat[j.category] || 0) + 1;

const first = items[0] || {};
const stats = {
  run_at: cfg.run_at,
  considered: items.length,
  capped_out: num(first.capped_out, 0),
  filter_stats: first.filter_stats || {},
  pool_by_category: byCat,
  quota_by_category: first.quota_by_category || {},
  pool_top_hosts: Object.entries(byHost)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 4)
    .map(([h, n]) => h + ' ' + n)
    .join(', '),
  same_story_collapsed: collapsed,
  eligible: unique.length,
  finalists: finalists.length,
  finalists_by_category: finalistsByCat,
  judge_budget: budget,
  judge_budget_capped: budget < cfg.judge_n,
  backlog_room: room,
  backlog_room_full_categories: present.filter((c) => catWeight(c) > 0 && roomIn(c) <= 0),
  hn_matched: num(first._hn_matched, 0),
  hn_lookups: num(first._hn_lookups, 0),
  hn_errors: num(first._hn_errors, 0),
  write_to_sheet: cfg.write_to_sheet,
  mark_read: cfg.mark_read,
};
console.log(
  'pick_finalists ' + JSON.stringify({ eligible: unique.length, collapsed, budget, room: roomTotal, finalists: finalistsByCat })
);

// A full backlog means zero judge calls, which is the point - not an error.
if (finalists.length === 0) return [{ json: { no_selection: true, _stats: stats, _runners_up: [] } }];
return finalists.map((j) => ({ json: { ...j, _stats: stats } }));

// Excerpt-only feed: the judge needs the real article, not two sentences.
const j = $('loop_judge_finalists').first().json;
const dl = $json || {};
const text = String(dl.contentMkdown || dl.content || '').trim();
return [{
  json: {
    ...j,
    judge_content: (text || j.excerpt || '').slice(0, 12000),
    content_source: text ? 'download_content' : 'download_failed',
    ogImageUrl: dl.ogImageUrl || '',
  },
}];

// Miniflux already has the full article, so skip the Download Content fetch.
const j = $('loop_judge_finalists').first().json;
return [{ json: { ...j, judge_content: (j.content_text || j.excerpt || '').slice(0, 12000), content_source: 'miniflux' } }];

// Merge the verdict onto the finalist. There is exactly one article per call now, so
// an unparseable response costs one candidate instead of twenty: the batched triage
// stage this replaced returned a 200 carrying broken JSON on one run and silently
// deleted a whole batch of 20, which retryOnFail never sees because the transport
// succeeded. A failure here scores 0, is flagged, and is named in the digest.
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const HOOKS = ['CONTRARIAN', 'WAR_STORY', 'MISCONCEPTION', 'TRADE_OFF', 'NEWS_REACTION', 'HARD_NUMBER'];

const j = $('loop_judge_finalists').first().json;
const raw = String($json.text || $json.output || '');
let body = raw;
const tagged = raw.match(/<output>([\s\S]*?)<\/output>/i);
if (tagged) body = tagged[1];
body = body.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const s = body.indexOf('{');
const e = body.lastIndexOf('}');
if (s >= 0 && e > s) body = body.slice(s, e + 1);

// Which branch fed the judge - Miniflux's own body or a Download Content fetch -
// only exists on the build_judge_vars_* item, and the loop hands parse_judge the
// pre-judge finalist instead. Read it back from whichever branch ran, guarded by
// cid: the branch that did not run still holds a previous iteration's item, and its
// cid will not match.
const contentSource = (() => {
  for (const name of ['build_judge_vars_downloaded', 'build_judge_vars_local']) {
    try {
      const v = $(name).first().json;
      if (v && v.cid === j.cid) return v.content_source || '';
    } catch (err) {
      /* branch never ran in this execution */
    }
  }
  return j.thin_content ? 'download_unknown' : 'miniflux';
})();

let v = {};
let ok = true;
try {
  v = JSON.parse(body) || {};
  if (typeof v.postability !== 'number') throw new Error('no postability in verdict');
} catch (err) {
  ok = false;
  console.log('WARNING parse_judge: unusable verdict for ' + j.cid + ' (' + j.host + '): ' + String(err.message).slice(0, 140));
}

return [{
  json: {
    ...j,
    postability: ok ? clamp(Math.round(num(v.postability, 0)), 0, 10) : 0,
    judge_blocked: ok ? !!v.blocked : false,
    hook: HOOKS.includes(String(v.hook || '').toUpperCase()) ? String(v.hook).toUpperCase() : '',
    angle: String(v.angle || '').slice(0, 240),
    evidence: String(v.evidence || '').slice(0, 200),
    content_source: contentSource,
    judged: ok,
  },
}];

// Slack digest. It is the whole product while write_to_sheet is false, and the only
// place a silent degradation becomes visible: a dead source, a source that is being
// starved by the pool quotas, a judge call that came back unparseable, a backlog that
// has quietly filled up. Anything that shrinks what reaches the queue gets a line here,
// not just a console.log nobody reads.
const items = $input.all().map((i) => i.json);
const first = items[0] || {};
const stats = first._stats || {};
const noRoom = first._runners_up || [];
const fs = stats.filter_stats || {};
const fmt = (n) => (typeof n === 'number' ? n.toFixed(2) : '-');
const kv = (o) => Object.entries(o || {}).map(([k, n]) => k + ' ' + n).join(' · ');

const lines = [];

if (first.no_selection) {
  if (stats.cleared_floor > 0) {
    lines.push(':package: *Content Feed Curator* - ' + stats.cleared_floor + ' cleared the judge but the backlog had no room.');
  } else {
    lines.push(':warning: *Content Feed Curator* - nothing cleared the judge today.');
  }
} else {
  lines.push(':inbox_tray: *Content Feed Curator* - added ' + items.length + ' to the backlog');
  lines.push('');
  for (const j of items) {
    const f = j.features || {};
    lines.push('*' + j.rank + '. ' + j.TITLE + '*');
    lines.push('<' + j.URL + '|' + j.SOURCE + '>  ·  ' + j.TOPIC + '  ·  score *' + fmt(j.SCORE) + '*  ·  ' + j.PRIORITY);
    lines.push('_' + (j.RATIONALE || 'no evidence returned') + '_');
    if (j.angle) lines.push('*brief:* ' + j.angle);
    const bits = ['post ' + j.postability + '/10', 'topic ' + fmt(f.affinity), 'eng ' + fmt(f.engagement), 'fresh ' + fmt(f.recency)];
    if ((j.topic_hits || []).length) bits.push(j.topic_hits.join(', '));
    if (j.hn_points) bits.push('HN ' + j.hn_points + 'pts/' + j.hn_comments + 'c' + (j.hn_hot ? ' :fire:' : ''));
    if (j.hook) bits.push('hook ' + j.hook);
    if (j.source !== 'miniflux') bits.push('via ' + j.source);
    if ((j.also_from || []).length) bits.push('also on ' + j.also_from.join('/'));
    if (j.content_source === 'download_content') bits.push(':inbox_tray: fetched full text');
    else if (j.content_source === 'download_failed') bits.push(':warning: fetch failed, judged on excerpt');
    else if (j.thin_content) bits.push(':scissors: excerpt only');
    lines.push('`' + bits.join('  |  ') + '`');
    lines.push('');
  }
}

// The backlog is the product now - one row of it gets published per sharing run - so its
// depth per category is the number to read first. A category at 0 will not be publishable
// however good the rest of the run looked.
lines.push(
  '*Backlog* ' + (stats.backlog_before || 0) + ' → ' + (stats.backlog_after || 0) +
    ' of ' + (stats.backlog_max_per_category ? stats.backlog_max_per_category + '/category' : 'cap') +
    '  `' + (kv(stats.backlog_depth) || 'empty') + '`'
);
if (noRoom.length) {
  lines.push('*Cleared the judge, no room*');
  for (const r of noRoom) lines.push('· <' + r.url + '|' + r.title + '> (' + fmt(r.score) + ') - ' + (r.why || ''));
}
lines.push('');

lines.push(
  '`sources: ' + (kv(fs.per_source) || '-') +
    // Hacker News candidates are routed into Data/AI/DevOps by title; one matching no
    // category's keywords is dropped there rather than parked in a category of its own.
    (fs.hn_unrouted ? ' · hn unrouted ' + fs.hn_unrouted : '') +
    ' → ' + (fs.total || 0) + ' raw`'
);
lines.push(
  '`dropped: off-topic ' + (fs.excluded_category || 0) +
    ' · already seen ' + (fs.seen_in_sheet || 0) +
    ' · blocklisted ' + (fs.blocked || 0) +
    ' · same story ' + (fs.merged || 0) +
    ' · short title ' + (fs.no_title || 0) +
    ' · over cap ' + (stats.capped_out || 0) +
    '`'
);
// quota vs filled, always: it is the one line that shows whether a source you added is
// actually reaching the judge. Hacker News contributed 40 candidates and got 1 pool slot
// on the run before quotas existed, and nothing in the digest said so.
lines.push('`quota ' + (kv(stats.quota_by_category) || '-') + '  ->  filled ' + (kv(stats.pool_by_category) || '-') + '`');
lines.push(
  '`pool ' + (stats.considered || 0) +
    ' · collapsed ' + (stats.same_story_collapsed || 0) +
    ' · judged ' + (stats.judged || 0) + '/' + (stats.finalists || 0) +
    (stats.judge_budget_capped ? ' (budget ' + stats.judge_budget + ', room ' + stats.backlog_room + ')' : '') +
    ' · blocked ' + (stats.judge_blocked || 0) +
    ' · unpostable ' + (stats.judge_unpostable || 0) +
    ' · cleared ' + (stats.cleared_floor || 0) +
    ' · admitted ' + (stats.admitted || 0) +
    '`'
);
// Which categories the judge calls are actually buying admissions in. This is the input to
// the category_weights decision - an aggregate block rate cannot tell a bad weight from a
// strict judge.
if ((stats.judge_yield_by_category || []).length) {
  lines.push('`cleared/judged  ' + stats.judge_yield_by_category.join(' · ') + '`');
}
lines.push(
  '`HN ' + (stats.hn_matched || 0) + '/' + (stats.considered || 0) + ' matched, ' + (stats.hn_lookups || 0) + ' lookup(s)' +
    (stats.hn_errors ? ' · :warning: ' + stats.hn_errors + ' request error(s)' : '') +
    '`'
);

// A judge call can return 200 with unparseable JSON, which retryOnFail never sees.
// One call is one article now, so this is a bounded loss - but say it out loud.
if (stats.judge_failed) {
  lines.push(':rotating_light: _' + stats.judge_failed + ' judge verdict(s) came back unusable and scored 0. Check the OpenRouter finish reason._');
}
if ((fs.source_errors || []).length) {
  lines.push(':rotating_light: _Source failure: ' + fs.source_errors.join(' | ') + '_');
}
if (fs.truncated) {
  lines.push(':rotating_light: _Miniflux window truncated - raise `max_entries_per_category`._');
}
// A starving category cannot be published from, and topic rotation on the drain side
// makes that worse rather than better - it will skip to another topic and this one stays
// empty. Name it before the queue runs dry.
const empties = Object.entries(stats.backlog_depth || {}).filter(([, n]) => n === 0).map(([c]) => c);
if (empties.length) lines.push(':warning: _Backlog empty for: ' + empties.join(', ') + '._');
// The mirror image: a full category is skipped by pick_finalists rather than judged and
// rejected, so its candidates go unread. Worth knowing which topic stopped listening.
const full = stats.backlog_room_full_categories || [];
if (full.length) lines.push('_At ' + stats.backlog_max_per_category + '/category and not judged this run: ' + full.join(', ') + '._');
// A TTL under the intake window admits rows that are already dead - judged, admitted,
// expired without ever reaching a slot. The run cannot fix it, so it has to be loud.
if ((stats.ttl_below_floor || []).length) {
  lines.push(
    ':rotating_light: _`ttl_days` below the ' + stats.ttl_floor + '-day floor (`lookback_days` + the longest publish gap): ' +
      stats.ttl_below_floor.join(', ') + '. Rows on those hooks can be admitted already expired._'
  );
}
// Judging costs money; expiring unpublished rows wastes it. The buffer is intended, so
// this only fires once depth is more than double what the publish rate can ever drain.
if (stats.backlog_publishable && stats.backlog_after > stats.backlog_publishable * 2) {
  lines.push(
    ':warning: _Backlog is ' + stats.backlog_after + ' against ~' + stats.backlog_publishable +
      ' that can publish inside a row\'s TTL, at ~' + (stats.judge_cost_per_post || 0) +
      ' judge calls per published post. Lower `max_per_category` if the buffer is not worth that._'
  );
}
if (!stats.write_to_sheet) {
  lines.push('_Dry run: write_to_sheet is false, so nothing was appended and the backlog above is what the sheet already held._');
}

return [{ json: { digest_text: lines.join('\n'), selected: items.length, stats } }];

// Backlog maintenance. The queue is durable now, so this no longer expires every
// unposted AUTO row each run - that was throwing away four judged winners per run to
// publish one. It expires only what should not be published any more:
//
//   1. STALE - past its TTL. Measured from PUBLISHED_AT, the article's own date, not
//      from when we queued it: a launch note is stale ten days after the launch
//      regardless of when it reached the sheet. The TTL comes from the judge's hook,
//      which is the field that already knows whether a piece is perishable -
//      NEWS_REACTION dies in days, a TRADE_OFF or WAR_STORY keeps for weeks. The hook
//      is read back out of the "Hook: X." prefix on EXTRA_PROMPT because content_queue
//      has no HOOK column.
//   2. SURPLUS - over the per-category or global cap, lowest SCORE first. Admission
//      already respects both caps, so this only fires when a cap was lowered in config
//      or rows were added by hand.
//
// ORIGIN=MANUAL is never touched, and neither is anything past QUEUE - IN_PROGRESS,
// WAITING_APPROVAL and PUBLISHED are somebody else's business.
const cfg = $('parse_curator_config').first().json;
const bl = cfg.backlog;
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);

const rows = $('read_articles_sheet').all().map((i) => i.json).filter((r) => r && r.row_number);
const mine = rows.filter(
  (r) => String(r.STATUS || '').trim() === 'QUEUE' && String(r.ORIGIN || '').trim() === 'AUTO'
);

const nowMs = new Date(cfg.run_at).getTime();
const hookOf = (r) => {
  const m = String(r.EXTRA_PROMPT || '').match(/^Hook:\s*([A-Z_]+)\./);
  return m ? m[1] : '';
};
const ttlOf = (r) => {
  const h = hookOf(r);
  // An unknown hook gets the default rather than the short TTL: guessing "perishable"
  // would quietly bin evergreen rows queued before the hook was recorded.
  return num(bl.ttl_days[h], num(bl.ttl_days.default, 21));
};
const ageDaysOf = (r) => {
  const t = Date.parse(r.PUBLISHED_AT || '') || Date.parse(r.UPDATE_DATE || '');
  return isFinite(t) ? (nowMs - t) / 86400000 : 0;
};

const stale = [];
const keep = [];
for (const r of mine) {
  const age = ageDaysOf(r);
  const ttl = ttlOf(r);
  if (age > ttl) stale.push({ r, why: 'stale ' + Math.round(age) + 'd > ' + ttl + 'd (' + (hookOf(r) || 'no hook') + ')' });
  else keep.push(r);
}

// Surplus is measured against what survives plus what is being admitted this run, so
// the two nodes cannot both decide there is room for the same slot.
const incoming = $('admit_to_backlog').all().map((i) => i.json).filter((j) => j && !j.no_selection);
const incomingByCat = new Map();
for (const j of incoming) {
  const c = String(j.TOPIC || '').trim() || 'unknown';
  incomingByCat.set(c, (incomingByCat.get(c) || 0) + 1);
}
// Manual rows occupy the backlog too, so they count towards the caps even though they
// can never be expired by this node.
const manualQueued = rows.filter(
  (r) => String(r.STATUS || '').trim() === 'QUEUE' && String(r.ORIGIN || '').trim() !== 'AUTO'
);

const surplus = [];
const worstFirst = (a, b) => num(Number(a.SCORE), 0) - num(Number(b.SCORE), 0) || b.row_number - a.row_number;

const byCat = new Map();
for (const r of keep) {
  const c = String(r.TOPIC || '').trim() || 'unknown';
  if (!byCat.has(c)) byCat.set(c, []);
  byCat.get(c).push(r);
}
const survivors = new Set(keep.map((r) => r.row_number));
for (const [cat, list] of byCat) {
  const manual = manualQueued.filter((r) => (String(r.TOPIC || '').trim() || 'unknown') === cat).length;
  const room = bl.max_per_category - (incomingByCat.get(cat) || 0) - manual;
  if (list.length <= room) continue;
  for (const r of list.slice().sort(worstFirst).slice(0, list.length - Math.max(0, room))) {
    surplus.push({ r, why: cat + ' over cap ' + bl.max_per_category });
    survivors.delete(r.row_number);
  }
}
// Global backstop, after the per-category pass.
const globalRoom = bl.max_total - incoming.length - manualQueued.length;
const stillHere = keep.filter((r) => survivors.has(r.row_number));
if (stillHere.length > globalRoom) {
  for (const r of stillHere.slice().sort(worstFirst).slice(0, stillHere.length - Math.max(0, globalRoom))) {
    surplus.push({ r, why: 'backlog over ' + bl.max_total });
    survivors.delete(r.row_number);
  }
}

const out = [...stale, ...surplus];
console.log(
  'build_expire_rows: ' + out.length + ' of ' + mine.length + ' AUTO/QUEUE rows expiring (' +
    stale.length + ' stale, ' + surplus.length + ' surplus); ' + survivors.size + ' kept'
);
for (const o of out.slice(0, 10)) console.log('  expire r' + o.r.row_number + ' ' + o.why + ' - ' + String(o.r.TITLE || '').slice(0, 60));

// The Google Sheets update node needs at least one item to not error on an empty input,
// and alwaysOutputData upstream would hand it a junk row. Return nothing and let the
// node be skipped: n8n does not run a node with zero input items.
return out.map((o) => ({ json: { row_number: o.r.row_number, TITLE: o.r.TITLE || '', reason: o.why } }));

// Mark the whole fetched Miniflux window read, not just the candidates that survived
// the cap. 205 entries per run were being dropped by the cap and left unread, so they
// were re-fetched the next run at full cost while only scoring worse on recency.
// Hacker News candidates have no entry_id - there is nothing to mark.
const fetched = $('fetch_candidates')
  .all()
  .map((i) => i.json)
  .filter((j) => j && j.source === 'miniflux' && j.entry_id);
const entryIds = [...new Set(fetched.map((j) => j.entry_id))];
console.log('build_mark_read_payload: marking ' + entryIds.length + ' Miniflux entries read');
if (entryIds.length === 0) return [{ json: { entry_ids: [], status: 'read', skipped: true } }];
return [{ json: { entry_ids: entryIds, status: 'read', skipped: false } }];

// Admission control, not selection. The queue is a durable backlog now, so this node
// does not build a slate of five - it adds whatever cleared the judge, up to whatever
// room the backlog has.
//
// Why: LinkedIn Post Sharing publishes exactly ONE row per run (select_article_to_post
// ends in slice(0, 1)). The old design spent 16 judge calls to produce five options,
// published one, and expired the other four on the next run - then re-fetched and
// re-judged from scratch. Four articles the judge had scored 8+ were thrown away every
// run while the same run reported a short slate. Keeping them costs nothing.
//
// So: no top_n, no per-domain slate cap, no relax ladder. Variety is decided on the way
// OUT, by topic rotation in select_article_to_post, which can guarantee it across a week
// instead of fighting for it inside one slate.
const cfg = $('parse_curator_config').first().json;
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const round = (v, d) => Math.round(v * Math.pow(10, d)) / Math.pow(10, d);
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const canonicalRow = (u) =>
  String(u || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[?#].*$/, '')
    .replace(/\/+$/, '');

const items = $input.all().map((i) => i.json).filter((j) => j && j.cid);
const stats = { ...(($('pick_finalists').first().json || {})._stats || {}) };

// The backlog as it stands, read at the top of the run.
const rows = $('read_articles_sheet').all().map((i) => i.json).filter((r) => r && r.URL);
const queued = rows.filter((r) => String(r.STATUS || '').trim() === 'QUEUE');
// Every URL in the sheet, whatever its STATUS and whatever category it sits under.
// filter_candidates already dropped these upstream; this is the guard that makes the
// per-category backlogs safe to reason about - a link lives in exactly one of them.
const everSeen = new Set(rows.map((r) => canonicalRow(r.URL)));

const backlogByCategory = new Map();
const backlogByHost = new Map();
for (const r of queued) {
  const cat = String(r.TOPIC || '').trim() || 'unknown';
  const host = String(r.SOURCE || '').trim();
  backlogByCategory.set(cat, (backlogByCategory.get(cat) || 0) + 1);
  if (host) backlogByHost.set(host, (backlogByHost.get(host) || 0) + 1);
}

const catWeight = (j) =>
  cfg.category_weights[j.category] != null ? cfg.category_weights[j.category] : num(cfg.category_weights.default, 0.8);

const scored = items.map((j) => {
  const hot = num(j.hn_points, 0) + num(j.hn_comments, 0) >= cfg.hn_hot_points;
  const score = clamp(
    (num(j.postability, 0) / 10) * catWeight(j) + (hot ? cfg.hn_boost : 0) + (j.starred ? cfg.starred_boost : 0),
    0,
    1
  );
  return { ...j, hn_hot: hot, category_weight: catWeight(j), score: round(score, 4) };
});

// postability 0-3 means "nothing to build on", and no amount of attention should
// override that. A viral launch note with a feature list and no numbers scored 0.66
// and reached the queue before this floor existed.
const blocked = scored.filter((j) => j.judge_blocked).length;
const failed = scored.filter((j) => !j.judged).length;
const cleared = scored
  .filter((j) => j.judged && !j.judge_blocked && num(j.postability, 0) >= cfg.min_postability)
  .sort((a, b) => b.score - a.score || a.hours_old - b.hours_old);

const bl = cfg.backlog;
const admitted = [];
const rejected = [];
let totalQueued = queued.length;
const seenThisRun = new Set();

for (const j of cleared) {
  const cat = j.category || 'unknown';
  const host = j.host || '';
  const key = canonicalRow(j.url);
  let why = '';
  if (everSeen.has(key) || seenThisRun.has(key)) why = 'already in the sheet';
  else if (totalQueued >= bl.max_total) why = 'backlog full (' + bl.max_total + ')';
  else if ((backlogByCategory.get(cat) || 0) >= bl.max_per_category) why = cat + ' backlog full (' + bl.max_per_category + ')';
  else if (host && (backlogByHost.get(host) || 0) >= cfg.max_per_host) why = host + ' at ' + cfg.max_per_host + ' in backlog';

  if (why) {
    rejected.push({ title: j.title, host: j.host, score: j.score, url: j.url, why });
    continue;
  }
  seenThisRun.add(key);
  backlogByCategory.set(cat, (backlogByCategory.get(cat) || 0) + 1);
  if (host) backlogByHost.set(host, (backlogByHost.get(host) || 0) + 1);
  totalQueued++;
  admitted.push(j);
}

const bands = cfg.priority_bands;
const priorityOf = (s) => (s >= bands.VERY_HIGH ? 'VERY_HIGH' : s >= bands.HIGH ? 'HIGH' : s >= bands.MEDIUM ? 'MEDIUM' : 'LOW');

const depth = {};
for (const [cat, n] of backlogByCategory) depth[cat] = n;
stats.judged = items.filter((j) => j.judged).length;
stats.judge_failed = failed;
stats.judge_blocked = blocked;
stats.judge_unpostable = scored.length - blocked - failed - cleared.length;
stats.cleared_floor = cleared.length;
stats.admitted = admitted.length;
stats.no_room = rejected.length;
stats.backlog_before = queued.length;
stats.backlog_after = totalQueued;
stats.backlog_depth = depth;
stats.backlog_max_per_category = bl.max_per_category;
// Yield PER CATEGORY, because the aggregate "blocked 13 of 23" cannot answer the only
// question worth asking about category_weights: is a category's weight wrong, or is the
// judge just strict? Tech sits at 0.65 and is documented as rarely postable, but nothing
// in the digest has ever shown whether Tech actually blocks harder than AI - so the
// decision to zero it, the way News is zeroed, has never had data behind it. One run is
// noise; three runs of this line is an answer.
const yieldByCat = {};
for (const j of scored) {
  const c = j.category || 'unknown';
  if (!yieldByCat[c]) yieldByCat[c] = { n: 0, ok: 0 };
  yieldByCat[c].n++;
  if (j.judged && !j.judge_blocked && num(j.postability, 0) >= cfg.min_postability) yieldByCat[c].ok++;
}
stats.judge_yield_by_category = Object.entries(yieldByCat)
  .sort((a, b) => b[1].n - a[1].n)
  .map(([c, v]) => c + ' ' + v.ok + '/' + v.n);
// How many rows can actually reach LinkedIn before the TTL bins them: the publish rate
// times the default TTL. Depth beyond this is reserve, and reserve costs judge calls.
stats.backlog_publishable = Math.ceil((cfg.publish_per_week * num(bl.ttl_days.default, 21)) / 7);
// A TTL shorter than the intake window admits rows that are already dead. NEWS_REACTION
// was 4 days against a lookback of 5, so an article at the edge of the window was judged,
// admitted and expired without ever reaching a publish slot. The floor is the intake
// window plus the longest gap between slots (Fri -> Mon = 3), so every admitted row gets
// at least one shot. This is a config error the run cannot fix, so it is reported loudly.
stats.ttl_floor = num(cfg.lookback_days, 5) + 3;
stats.ttl_below_floor = Object.entries(bl.ttl_days)
  .filter(([, d]) => num(d, 999) < stats.ttl_floor)
  .map(([h, d]) => h + ' ' + d + 'd');
// The honest cost of the buffer: judge calls spent per post that actually goes out. The
// curator and the publisher both run publish_per_week times a week, so one run's judge
// calls is one published post's worth of spend.
stats.judge_cost_per_post = stats.judged;
console.log(
  'admit_to_backlog ' + JSON.stringify({ cleared: cleared.length, admitted: admitted.length, no_room: rejected.length, backlog: totalQueued })
);

// Nothing admitted is a normal outcome now: either the judge found nothing, or the
// backlog is already deep. Those are different states and the digest says which.
if (admitted.length === 0) return [{ json: { no_selection: true, _stats: stats, _runners_up: rejected.slice(0, 5) } }];

return admitted.map((j, i) => ({
  json: {
    rank: i + 1,
    URL: j.url,
    TITLE: j.title,
    STATUS: 'QUEUE',
    PRIORITY: priorityOf(j.score),
    SCORE: j.score,
    ORIGIN: 'AUTO',
    TOPIC: j.category,
    SOURCE: j.host,
    RATIONALE: j.evidence,
    // The angle from the judge is the brief the post generator writes from. The
    // leading "Hook: X." is also how build_expire_rows recovers the hook to pick a
    // TTL, since content_queue has no HOOK column.
    EXTRA_PROMPT: (j.hook ? 'Hook: ' + j.hook + '. ' : '') + (j.angle || ''),
    MAX_WORDS: 300,
    PUBLISHED_AT: j.published_at,
    UPDATE_DATE: cfg.run_at,
    RELEASE_DATE: '',
    LINKEDIN_URL: '',
    // Only Miniflux entries have one, and it is what mark_entries_read needs.
    ENTRY_ID: j.entry_id || '',
    ERROR: '',
    EXECUTION_ID: $execution.id,
    no_selection: false,
    hook: j.hook,
    angle: j.angle,
    source: j.source,
    also_from: j.also_from || [],
    content_source: j.content_source,
    thin_content: j.thin_content,
    postability: j.postability,
    features: {
      postability: round(num(j.postability, 0) / 10, 3),
      affinity: j.f_affinity,
      engagement: j.f_engagement,
      recency: j.f_recency,
      category_weight: j.category_weight,
    },
    topic_hits: j.topic_hits,
    hn_points: j.hn_points,
    hn_comments: j.hn_comments,
    hn_hot: j.hn_hot,
    discussion_url: j.discussion_url,
    ...(i === 0 ? { _stats: stats, _runners_up: rejected.slice(0, 5) } : {}),
  },
}));

// Re-emit the admitted rows, one item per sheet row, immediately before the append.
//
// Why this node exists at all: if_write_to_sheet is four nodes downstream of
// admit_to_backlog, and everything between them collapses the stream to a single item -
// build_digest returns one digest, notify_digest replaces it with Slack's API response.
// So append_content_queue was receiving {ok, channel, message: {...}} and every
// ={{ $json.URL }} mapping resolved to undefined. It appended one blank row per run and
// reported success, because an append of undefined values is not an error.
//
// n8n has no way to "go back" to an earlier node's items in a mapping - a node reference in
// an expression reads ONE item, not the list - so restoring the stream needs a code node.
// This is the standard shape for it: read the named node, re-emit.
//
// Only the 18 sheet columns are emitted. admit_to_backlog's items also carry _stats,
// features, topic_hits and the rest, which the append does not map and nobody downstream
// reads; dropping them here keeps what reaches Google Sheets equal to what the header says.
const COLUMNS = [
  'URL',
  'TITLE',
  'STATUS',
  'PRIORITY',
  'SCORE',
  'ORIGIN',
  'TOPIC',
  'SOURCE',
  'RATIONALE',
  'EXTRA_PROMPT',
  'MAX_WORDS',
  'PUBLISHED_AT',
  'UPDATE_DATE',
  'RELEASE_DATE',
  'LINKEDIN_URL',
  'ENTRY_ID',
  'ERROR',
  'EXECUTION_ID',
];

// admit_to_backlog emits a single { no_selection: true } item when nothing cleared the
// judge or the backlog had no room. That is a normal outcome, not a row - if it reached the
// append it would be the blank-row bug again, wearing a different hat.
const rows = $('admit_to_backlog')
  .all()
  .map((i) => i.json)
  .filter((j) => j && j.no_selection !== true && j.URL);

console.log('build_queue_rows: ' + rows.length + ' row(s) to append');

return rows.map((r) => {
  const out = {};
  for (const c of COLUMNS) out[c] = r[c] != null ? r[c] : '';
  return { json: out };
});

// Parse datasets/curator_config.json (fetched as text by DownloadTemplate) into a
// single validated item that every downstream node reads via
// $('parse_curator_config').first().json. Missing keys fall back to defaults, so a
// partial config file can never take the run down.
const raw = $json.output || '{}';
let cfg;
try {
  cfg = JSON.parse(raw);
} catch (e) {
  throw new Error('datasets/curator_config.json is not valid JSON: ' + e.message);
}

const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const bool = (v, d) => (typeof v === 'boolean' ? v : d);
const arr = (v, d) => (Array.isArray(v) ? v : d);
const obj = (v, d) => (v && typeof v === 'object' && !Array.isArray(v) ? v : d);

const sources = obj(cfg.sources, {});
const hnTop = obj(sources.hn_top, {});
const backlog = obj(cfg.backlog, {});

const out = {
  lookback_days: num(cfg.lookback_days, 5),
  max_entries_per_category: num(cfg.max_entries_per_category, 1000),
  min_title_chars: num(cfg.min_title_chars, 15),
  min_content_words: num(cfg.min_content_words, 120),

  max_candidates: num(cfg.max_candidates, 60),
  // Per-category pool share is derived from category_weights in rank_candidates, so
  // there is deliberately no max_per_category knob: a flat ceiling is what let Tech
  // take 20 of 60 slots while Hacker News got 1.
  max_per_host: num(cfg.max_per_host, 3),
  judge_n: num(cfg.judge_n, 24),
  min_postability: num(cfg.min_postability, 4),

  // The queue is a durable backlog drained one row per sharing run, so there is no
  // top_n / max_per_domain / max_per_category_in_top any more: nothing builds a slate
  // of five. Variety is decided on the way out by topic rotation.
  //
  // These fallbacks MUST track the config file. They are what a broken or truncated
  // download degrades to, and a stale fallback is a silent config rollback: the
  // NEWS_REACTION default sat at 4 against a lookback of 5, which is the arithmetic that
  // admitted news rows already past their TTL. Every value here must clear lookback_days
  // plus the longest publish gap for the same reason.
  backlog: {
    max_per_category: num(backlog.max_per_category, 10),
    max_total: num(backlog.max_total, 60),
    ttl_days: obj(backlog.ttl_days, { NEWS_REACTION: 10, HARD_NUMBER: 45, default: 60 }),
  },

  // Only used to warn in the digest when the backlog holds more than the TTL window can
  // ever publish. Nothing gates on it - the publish schedule lives in LinkedIn Post Sharing.
  publish_per_week: Math.max(1, num(cfg.publish_per_week, 3)),

  mark_read: bool(cfg.mark_read, false),
  write_to_sheet: bool(cfg.write_to_sheet, false),
  http_concurrency: Math.max(1, num(cfg.http_concurrency, 6)),

  hn_engagement: bool(cfg.hn_engagement, true),
  hn_hot_points: num(cfg.hn_hot_points, 100),
  hn_boost: num(cfg.hn_boost, 0.1),
  starred_boost: num(cfg.starred_boost, 0.05),

  sources: {
    hn_top: {
      enabled: bool(hnTop.enabled, true),
      min_points: num(hnTop.min_points, 80),
      limit: num(hnTop.limit, 40),
    },
  },

  priority_bands: obj(cfg.priority_bands, { VERY_HIGH: 0.8, HIGH: 0.65, MEDIUM: 0.5 }),
  // default 0 - with three wanted categories, anything else is something new in Miniflux
  // that nobody has weighted yet, and 0 pool slots is the safe reading of "undecided".
  category_weights: obj(cfg.category_weights, { default: 0 }),
  exclude_categories: arr(cfg.exclude_categories, []).map((s) => String(s)),
  aggregator_hosts: arr(cfg.aggregator_hosts, []).map((s) => String(s).toLowerCase()),
  domain_blocklist: arr(cfg.domain_blocklist, []).map((s) => String(s).toLowerCase()),
  title_blocklist: arr(cfg.title_blocklist, []).map((s) => String(s).toLowerCase()),
  shared_keywords: arr(cfg.shared_keywords, []).map((s) => String(s).toLowerCase()),
};

// The keyword list is edited per category - the per-category lists route Hacker News
// candidates, which arrive with no category of their own - and rank_candidates wants one
// flat list for the affinity count. Derive the flat one rather than keeping both in the
// file, so a term added to a category cannot be missing from the affinity vocabulary.
const rawCatKw = obj(cfg.category_keywords, {});
out.category_keywords = {};
for (const cat of Object.keys(rawCatKw)) {
  out.category_keywords[cat] = arr(rawCatKw[cat], []).map((s) => String(s).toLowerCase());
}
out.topic_keywords = [
  ...new Set([...Object.values(out.category_keywords).flat(), ...out.shared_keywords]),
];

const nowMs = Date.now();
out.run_at = new Date(nowMs).toISOString();
out.published_after = Math.floor((nowMs - out.lookback_days * 86400000) / 1000);

return [{ json: out }];

// Every source, one output shape. Downstream nodes read $('fetch_candidates') and
// never care where a candidate came from: same fields, same units, one item each.
//
// Each source is wrapped in its own try/catch. The Algolia API has outages, and that is
// not a reason to skip a run that Miniflux alone could still curate - the failure lands
// in source_errors and is printed in the Slack digest instead of throwing.
//
// Reddit used to be a third source and was removed. top.json 403s unauthenticated
// clients outright; top.rss worked for one run and then started returning 429 for
// subreddit after subreddit even at 7s spacing with the order rotated by day. Across its
// best run it contributed 5 candidates out of 839 and admitted none, for eight requests
// and up to a minute of wall clock. It needs a registered OAuth app to be worth having;
// until then the cost was all error noise.
//
// Miniflux is asked per category rather than once globally: a single query is
// ordered published_at desc and capped, so the highest-volume category eats the
// budget and the oldest part of the window is silently dropped. On the first real
// run 231 of 400 entries were News, which is excluded anyway, leaving ~19 real
// candidates out of a 792-entry window.
const cfg = $('parse_curator_config').first().json;
const nowMs = Date.now();
const sinceSec = cfg.published_after;

const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const hostOf = (u) => {
  try {
    return new URL(String(u)).hostname.replace(/^www\./, '').toLowerCase();
  } catch (e) {
    const m = String(u || '').match(/^[a-z]+:\/\/([^/?#]+)/i);
    return m ? m[1].replace(/^www\./, '').toLowerCase() : '';
  }
};
const stripHtml = (h) =>
  String(h || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
const stripTracking = (x) => {
  x.hash = '';
  x.hostname = x.hostname.replace(/^www\./, '').toLowerCase();
  const drop = [];
  x.searchParams.forEach((_, k) => {
    if (/^(utm_|ref$|ref_src$|source$|mc_cid$|mc_eid$|fbclid$|gclid$|igshid$|_hsenc$|_hsmi$|at_medium$|at_campaign$)/i.test(k)) drop.push(k);
  });
  drop.forEach((k) => x.searchParams.delete(k));
  x.pathname = x.pathname.replace(/\/+$/, '') || '/';
  return x;
};
// Identity for dedupe: no scheme, no tracking params, no trailing slash.
const canonical = (u) => {
  try {
    const x = stripTracking(new URL(String(u).trim()));
    const path = x.pathname === '/' ? '' : x.pathname;
    const qs = x.searchParams.toString();
    return (x.hostname + path + (qs ? '?' + qs : '')).toLowerCase();
  } catch (e) {
    return String(u || '').trim().toLowerCase();
  }
};
// What actually gets stored and published: the real URL minus the RSS tracking
// junk, so "Source here:" in the post is not a utm_source link.
const cleanUrl = (u) => {
  try {
    return stripTracking(new URL(String(u).trim())).toString().replace(/\?$/, '');
  } catch (e) {
    return String(u || '').trim();
  }
};

// One shape to rule them all. votes/comments are whatever the source already told
// us for free - Miniflux has none, so fetch_hn_signal fills those in later.
const candidate = (c) => {
  const text = String(c.text || '');
  const words = text ? text.split(' ').length : 0;
  const pubMs = c.published_at ? new Date(c.published_at).getTime() : NaN;
  return {
    source: c.source,
    entry_id: c.entry_id || '',
    url: cleanUrl(c.url),
    canonical_url: canonical(c.url),
    host: hostOf(c.url),
    title: String(c.title || '').trim(),
    author: c.author || '',
    category: c.category,
    feed_title: c.feed_title || '',
    published_at: c.published_at || null,
    hours_old: isFinite(pubMs) ? Math.max(0, (nowMs - pubMs) / 3600000) : 9999,
    starred: !!c.starred,
    votes: num(c.votes, 0),
    comments: num(c.comments, 0),
    discussion_url: c.discussion_url || '',
    hn_story_url: c.source === 'hn' ? c.discussion_url || '' : '',
    word_count: words,
    thin_content: words < cfg.min_content_words,
    excerpt: text.slice(0, 1200),
    content_text: text.slice(0, 8000),
  };
};

const out = [];
const perSource = {};
const errors = [];
let truncated = false;
const startedAt = Date.now();

// --- Miniflux -------------------------------------------------------------
try {
  const base = String($env.MINIFLUX_URL || '').replace(/\/+$/, '');
  if (!base) throw new Error('MINIFLUX_URL is not set on the n8n pod');
  const auth =
    'Basic ' + Buffer.from(String($env.MINIFLUX_API_USER) + ':' + String($env.MINIFLUX_API_PASSWORD)).toString('base64');
  const get = (url, qs) =>
    this.helpers.httpRequest({ method: 'GET', url, qs, headers: { Authorization: auth }, json: true, timeout: 30000 });

  const categories = await get(base + '/v1/categories', {});
  // Excluded categories are never fetched, so they cost nothing at all - Miniflux
  // has no "not this category" filter.
  const wanted = (Array.isArray(categories) ? categories : []).filter(
    (c) => c && c.title && !cfg.exclude_categories.includes(c.title)
  );

  let got = 0;
  for (const c of wanted) {
    const res = await get(base + '/v1/entries', {
      status: 'unread',
      category_id: c.id,
      order: 'published_at',
      direction: 'desc',
      limit: cfg.max_entries_per_category,
      published_after: sinceSec,
    });
    const entries = Array.isArray(res && res.entries) ? res.entries : [];
    const total = res && typeof res.total === 'number' ? res.total : entries.length;
    if (total > entries.length) {
      truncated = true;
      console.log('WARNING ' + c.title + ' truncated: ' + entries.length + ' of ' + total + ' - raise max_entries_per_category');
    }
    for (const e of entries) {
      out.push(
        candidate({
          source: 'miniflux',
          entry_id: e.id,
          url: e.url,
          title: e.title,
          author: e.author,
          category: (e.feed && e.feed.category && e.feed.category.title) || 'unknown',
          feed_title: (e.feed && e.feed.title) || '',
          published_at: e.published_at,
          starred: e.starred,
          text: stripHtml(e.content),
        })
      );
    }
    got += entries.length;
  }
  perSource.miniflux = got;
} catch (e) {
  perSource.miniflux = 0;
  errors.push('miniflux: ' + String((e && e.message) || e).slice(0, 160));
}

// --- Hacker News top stories ---------------------------------------------
// Not the same thing as fetch_hn_signal. That node asks "how popular is this
// article the feeds gave me"; this one treats the front page as a source in its
// own right, because 68 RSS feeds still miss the engineering writeup nobody
// syndicates. min_points is the whole filter: the crowd already triaged these.
//
// HN candidates are ROUTED into Data/AI/DevOps rather than carrying a category of their
// own. Giving them "HN" was a mistake: that category drew a pool quota of 12 and filled 2,
// because most HN links are correctly merged into the publisher's copy by filter_candidates
// before ranking - which is where HN's value actually is, since only HN knows the vote
// count. The survivors are the unsyndicated writeups the source was added for, so they are
// filed by whichever category's keywords their title matches most. A bare link has no
// excerpt, so the title is all there is; one matching nothing is dropped rather than parked
// in a fourth category, because zero affinity loses the quota race anyway.
const routeHn = (title) => {
  const t = ' ' + String(title || '').toLowerCase().replace(/[^a-z0-9+#]+/g, ' ') + ' ';
  let best = '';
  let bestHits = 0;
  let bestWeight = -1;
  for (const cat of Object.keys(cfg.category_keywords)) {
    if (cfg.exclude_categories.includes(cat)) continue;
    const weight = cfg.category_weights[cat] != null ? cfg.category_weights[cat] : num(cfg.category_weights.default, 0);
    if (weight <= 0) continue;
    let hits = 0;
    for (const term of cfg.category_keywords[cat]) {
      if (t.includes(' ' + term.replace(/[^a-z0-9+#]+/g, ' ') + ' ')) hits++;
    }
    // Ties break toward the heavier category, so a "kubernetes + kafka" title lands in the
    // one you would rather publish from instead of on list order.
    if (hits > bestHits || (hits > 0 && hits === bestHits && weight > bestWeight)) {
      best = cat;
      bestHits = hits;
      bestWeight = weight;
    }
  }
  return best;
};
let hnUnrouted = 0;

if (cfg.sources.hn_top.enabled) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://hn.algolia.com/api/v1/search_by_date',
      qs: {
        tags: 'story',
        numericFilters: 'created_at_i>' + sinceSec + ',points>' + cfg.sources.hn_top.min_points,
        hitsPerPage: cfg.sources.hn_top.limit,
      },
      json: true,
      timeout: 15000,
    });
    let kept = 0;
    for (const h of (res && res.hits) || []) {
      // Ask HN / Tell HN carry no URL, so there is nothing for the post generator
      // to cite or for Download Content to fetch.
      if (!h || !h.url) continue;
      const cat = routeHn(h.title || h.story_title);
      if (!cat) {
        hnUnrouted++;
        continue;
      }
      out.push(
        candidate({
          source: 'hn',
          url: h.url,
          title: h.title || h.story_title,
          author: h.author,
          category: cat,
          feed_title: 'Hacker News front page',
          published_at: h.created_at,
          votes: h.points,
          comments: h.num_comments,
          discussion_url: 'https://news.ycombinator.com/item?id=' + h.objectID,
          text: stripHtml(h.story_text),
        })
      );
      kept++;
    }
    perSource.hn = kept;
  } catch (e) {
    perSource.hn = 0;
    errors.push('hn_top: ' + String((e && e.message) || e).slice(0, 160));
  }
}

const stats = { per_source: perSource, source_errors: errors, truncated, total: out.length, hn_unrouted: hnUnrouted };
console.log('fetch_candidates: ' + out.length + ' raw candidate(s) in ' + (Date.now() - startedAt) + 'ms ' + JSON.stringify(stats));
if (errors.length) console.log('WARNING fetch_candidates source failures: ' + errors.join(' | '));

if (out.length === 0) return [{ json: { empty: true, _fetch_stats: stats } }];
return out.map((c) => ({ json: { ...c, _fetch_stats: stats } }));

// Everything that can be decided for free, decided before a token is spent: the
// blocklists, the sheet dedupe (a URL in either tab has already been through the
// chain, whatever its STATUS), and same-story collapse across sources.
//
// Collapse merges rather than discards. The same article arrives from both the blog's own
// feed and the Hacker News front page, and only Hacker News knows the vote count.
// Dropping the duplicate would throw that away, so the surviving copy inherits the
// highest votes/comments it saw.
// --- shared helpers (duplicated per Code node; n8n has no module scope) -------
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
// Fuzzy title identity. The same announcement gets rewritten by every outlet
// ("cut compaction cost by 40%" vs "reduce compaction costs 40 percent"), so an
// exact fingerprint does not catch syndication - token overlap does. Trailing
// plurals are stripped so cost/costs collapse.
const titleTokens = (t) =>
  new Set(
    String(t || '')
      .toLowerCase()
      .replace(/[^a-z0-9 ]/g, ' ')
      .split(/\s+/)
      // Keep short numeric tokens: they are the version, and dropping them makes
      // "Claude Opus 5" and "Claude Opus 4.6" look like the same story.
      .filter((w) => w.length > 3 || /\d/.test(w))
      .map((w) => w.replace(/s$/, ''))
  );
const jaccard = (a, b) => {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  return inter / (a.size + b.size - inter);
};
const canonicalRow = (u) =>
  String(u || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[?#].*$/, '')
    .replace(/\/+$/, '');
const TITLE_DUP_THRESHOLD = 0.55;

const cfg = $('parse_curator_config').first().json;
const fetched = $('fetch_candidates').all().map((i) => i.json).filter((j) => j && j.url && !j.empty);
const fetchStats = ($('fetch_candidates').first().json || {})._fetch_stats || { per_source: {}, source_errors: [], total: 0 };

// Both tabs: content_queue is the live queue, articles_2_linkedin is frozen
// history. A URL in either one has already been through the chain.
const rows = [...$('read_legacy_sheet').all(), ...$('read_articles_sheet').all()]
  .map((i) => i.json)
  .filter((r) => r && r.URL);
const seenUrls = new Set(rows.map((r) => canonicalRow(r.URL)));
const seenTitleSets = rows.map((r) => titleTokens(r.TITLE)).filter((s) => s.size >= 3);

const isAggregator = (host) => cfg.aggregator_hosts.some((h) => String(host || '').endsWith(h));

// Collapse is first-wins, so this ordering decides which copy of a story survives:
// a real publisher over an aggregator, then whoever arrived first. Votes are merged
// afterwards either way, so nothing is lost by preferring the publisher's copy.
const candidates = fetched
  .slice()
  .sort((a, b) => (isAggregator(a.host) ? 1 : 0) - (isAggregator(b.host) ? 1 : 0) || a.hours_old - b.hours_old);

const stats = {
  total: candidates.length,
  per_source: fetchStats.per_source,
  source_errors: fetchStats.source_errors,
  truncated: !!fetchStats.truncated,
  hn_unrouted: num(fetchStats.hn_unrouted, 0),
  excluded_category: 0,
  no_title: 0,
  seen_in_sheet: 0,
  blocked: 0,
  merged: 0,
  kept: 0,
};

const kept = [];
const keptByUrl = new Map();
const keptTitleSets = [];

for (const c of candidates) {
  if (cfg.exclude_categories.includes(c.category)) {
    stats.excluded_category++;
    continue;
  }
  if (!c.url || c.title.length < cfg.min_title_chars) {
    stats.no_title++;
    continue;
  }
  const tokens = titleTokens(c.title);
  if (
    seenUrls.has(c.canonical_url) ||
    (tokens.size >= 3 && seenTitleSets.some((s) => jaccard(tokens, s) >= TITLE_DUP_THRESHOLD))
  ) {
    stats.seen_in_sheet++;
    continue;
  }
  const lowerTitle = c.title.toLowerCase();
  if (
    cfg.title_blocklist.some((b) => lowerTitle.includes(b)) ||
    cfg.domain_blocklist.some((b) => c.canonical_url.includes(b))
  ) {
    stats.blocked++;
    continue;
  }

  // Same story as something already kept? Merge the crowd signal into it.
  let twin = keptByUrl.get(c.canonical_url) || null;
  if (!twin && tokens.size >= 3) {
    for (const k of kept) {
      if (k._tokens.size >= 3 && jaccard(tokens, k._tokens) >= TITLE_DUP_THRESHOLD) {
        twin = k;
        break;
      }
    }
  }
  if (twin) {
    stats.merged++;
    if (num(c.votes, 0) + num(c.comments, 0) > num(twin.votes, 0) + num(twin.comments, 0)) {
      twin.votes = num(c.votes, 0);
      twin.comments = num(c.comments, 0);
      twin.discussion_url = c.discussion_url || twin.discussion_url;
      if (c.hn_story_url) twin.hn_story_url = c.hn_story_url;
    }
    twin.also_from = [...new Set([...(twin.also_from || []), c.source])];
    // Miniflux is the only source with the full article body, so if the surviving
    // copy is a bare aggregator link and the duplicate has text, take the text.
    if (twin.thin_content && !c.thin_content) {
      twin.excerpt = c.excerpt;
      twin.content_text = c.content_text;
      twin.word_count = c.word_count;
      twin.thin_content = false;
    }
    if (!twin.entry_id && c.entry_id) twin.entry_id = c.entry_id;
    continue;
  }

  const row = { ...c, _tokens: tokens, also_from: [] };
  kept.push(row);
  keptByUrl.set(c.canonical_url, row);
  keptTitleSets.push(tokens);
  stats.kept++;
}

console.log('filter_candidates', JSON.stringify({ ...stats, source_errors: stats.source_errors.length }));
return kept.map((c) => {
  const { _tokens, ...rest } = c;
  return { json: { ...rest, _filter_stats: stats } };
});

// Rank for free, then cap. Only max_candidates candidates go on to the HN
// engagement lookup and only judge_n reach the LLM, so this node decides what the
// expensive stages ever get to see - with no network calls and no tokens.
//
// It replaces the buzz index, which cost ~140 Miniflux count queries per run to
// produce a number that was 0.9 for anything matching the vocabulary and 0.25 for
// anything else. That is not a trend signal, it is topic affinity with extra steps
// and a wall-clock bill - so measure topic affinity directly and keep the money.
//
// The one thing the old pre-rank got right and must not regress: ranking on recency
// alone threw away 204 candidates for being a few hours older than the rest.
const cfg = $('parse_curator_config').first().json;
const items = $input.all().map((i) => i.json).filter((j) => j && j.url);
const stats = (items[0] && items[0]._filter_stats) || { total: 0, kept: 0, per_source: {}, source_errors: [] };

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const escapeRx = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const terms = cfg.topic_keywords.map((t) => ({
  term: t,
  rx: new RegExp('(^|[^a-z0-9+#])' + escapeRx(t) + '([^a-z0-9+#]|$)', 'i'),
}));
// A concrete figure in the headline or opening is the single best free predictor of
// a postable article - it is what the judge's HARD_NUMBER hook needs and what the
// post generator opens with. Bare years are not numbers in that sense.
const NUMBER_RX = /\b\d+(?:[.,]\d+)?\s*(?:%|x\b|ms\b|µs\b|ns\b|s\b|gb\b|tb\b|pb\b|mb\b|kb\b|k\b|m\b|b\b|qps\b|rps\b|req\/s|tokens?\b|cores?\b|nodes?\b|times\b|percent\b|usd\b|\$)|\$\s*\d|\b\d+(?:[.,]\d+)?x\b/i;

const catWeight = (c) =>
  cfg.category_weights[c.category] != null ? cfg.category_weights[c.category] : num(cfg.category_weights.default, 0.8);

const scored = items.map((c) => {
  const title = String(c.title || '');
  const head = (c.excerpt || '').slice(0, 600);
  // Title hits count double: a keyword in the headline is what the article is
  // about, the same keyword in paragraph four is a passing mention.
  let hits = 0;
  const matched = [];
  for (const t of terms) {
    const inTitle = t.rx.test(title);
    const inBody = inTitle ? false : t.rx.test(head);
    if (!inTitle && !inBody) continue;
    hits += inTitle ? 2 : 1;
    matched.push(t.term);
  }
  const affinity = clamp(hits / 4, 0, 1);
  const hasNumber = NUMBER_RX.test(title) || NUMBER_RX.test(head);
  const substance = (hasNumber ? 0.6 : 0) + (c.thin_content ? 0 : 0.4);
  const recency = clamp(1 - c.hours_old / (cfg.lookback_days * 24), 0, 1);
  // Votes are free here: the aggregator sources already handed them over, and
  // filter_candidates merged them onto whichever copy survived. Miniflux-only
  // candidates sit at 0 and make the difference up on affinity - fetch_hn_signal
  // gives them their engagement number a step later.
  const votes = clamp(Math.log10(1 + num(c.votes, 0) + num(c.comments, 0)) / 2.5, 0, 1);

  const prerank = catWeight(c) * (0.45 * affinity + 0.2 * substance + 0.15 * recency + 0.2 * votes);
  return {
    ...c,
    topic_hits: matched.slice(0, 4),
    has_number: hasNumber,
    f_affinity: Math.round(affinity * 1000) / 1000,
    f_substance: substance,
    f_recency: Math.round(recency * 1000) / 1000,
    f_votes: Math.round(votes * 1000) / 1000,
    prerank: Math.round(prerank * 10000) / 10000,
  };
});

const sorted = scored
  .slice()
  .sort((a, b) => b.prerank - a.prerank || a.hours_old - b.hours_old);

// The pool is ALLOCATED, not filled first-come. A flat per-category ceiling gave the
// 60 slots to whichever category happened to have the most entries: Tech took 20 -
// weight 0.65, and the config calls it rarely postable - while Hacker News put 40
// candidates in and got 1 slot, because a bare link has no excerpt to match keywords
// against and so loses to any Miniflux article on affinity. Adding a source is
// pointless if the cap then deletes 39/40 of it.
//
// So each category gets a share of max_candidates proportional to its weight, over
// the categories actually present in this run, and competes only against itself.
// Within a category the thin-content penalty is a constant, so it stops distorting.
const present = [...new Set(items.map((c) => c.category))];
const totalWeight = present.reduce((s, c) => s + Math.max(0, catWeight({ category: c })), 0);
const quotaOf = new Map();
for (const cat of present) {
  const w = Math.max(0, catWeight({ category: cat }));
  // weight 0 means "never postable" (News), which is a zero, not one free slot.
  quotaOf.set(cat, w <= 0 || totalWeight <= 0 ? 0 : Math.max(1, Math.round((cfg.max_candidates * w) / totalWeight)));
}

const byCategory = new Map();
for (const c of sorted) {
  if (!byCategory.has(c.category)) byCategory.set(c.category, []);
  byCategory.get(c.category).push(c);
}

// One publisher took 8 of 60 pool slots on the run that motivated this (cncf.io),
// which is 8 judge calls that could return the same argument eight times. The slate
// already caps hosts; the pool feeding it has to as well or the cap has nothing
// diverse left to choose from.
const takenUrls = new Set();
const hostCount = new Map();
const kept = [];
const take = (list, limit) => {
  let n = 0;
  for (const c of list) {
    if (n >= limit || kept.length >= cfg.max_candidates) break;
    if (takenUrls.has(c.canonical_url)) continue;
    const h = c.host || '(no host)';
    if ((hostCount.get(h) || 0) >= cfg.max_per_host) continue;
    hostCount.set(h, (hostCount.get(h) || 0) + 1);
    takenUrls.add(c.canonical_url);
    kept.push(c);
    n++;
  }
  return n;
};

for (const [cat, list] of byCategory) take(list, quotaOf.get(cat) || 0);

// Unused quota is not wasted, but it is not handed out best-first either. Redistributing
// globally let ONE high-volume low-weight category absorb every spare slot: Hacker News
// could supply only 4 of its 10 (its duplicates are merged into the publisher's copy
// upstream, correctly) and Reddit 7 of 10, and Tech - 300 candidates at weight 0.65 -
// took all 9 leftovers and finished at 16 against a quota of 7. The judge then blocked 9
// of 16 finalists, because consumer tech is exactly what it is there to block. So the
// leftovers are re-allocated by weight over the categories that still have candidates,
// which is the same rule as the first pass, applied again.
const remainingIn = (cat) => (byCategory.get(cat) || []).filter((c) => !takenUrls.has(c.canonical_url)).length;
let guard = 0;
while (kept.length < cfg.max_candidates && guard++ < 20) {
  const hungry = present.filter((c) => catWeight({ category: c }) > 0 && remainingIn(c) > 0);
  if (!hungry.length) break;
  const slots = cfg.max_candidates - kept.length;
  const w = hungry.reduce((s, c) => s + catWeight({ category: c }), 0);
  let progress = 0;
  for (const cat of hungry) {
    if (kept.length >= cfg.max_candidates) break;
    const share = Math.max(1, Math.round((slots * catWeight({ category: cat })) / w));
    progress += take(byCategory.get(cat), share);
  }
  // Every remaining candidate is blocked by the host cap, so more rounds cannot help.
  if (!progress) break;
}

// Always emit one item so if_has_candidates can route an empty run to notify_empty.
if (kept.length === 0) return [{ json: { empty: true, considered: 0, filter_stats: stats } }];

const byCat = {};
for (const c of kept) byCat[c.category] = (byCat[c.category] || 0) + 1;
const quotaByCat = {};
for (const cat of present) quotaByCat[cat] = quotaOf.get(cat) || 0;
const dropped = sorted.length - kept.length;
console.log(
  'rank_candidates: kept ' + kept.length + ' of ' + sorted.length +
    ' | quota ' + JSON.stringify(quotaByCat) + ' | filled ' + JSON.stringify(byCat)
);

return kept.map((c, i) => ({
  json: {
    ...c,
    cid: 'c' + (i + 1),
    empty: false,
    considered: kept.length,
    capped_out: dropped,
    pool_by_category: byCat,
    quota_by_category: quotaByCat,
    filter_stats: stats,
  },
}));

// The one measured signal in the pipeline: how much attention this story is
// actually getting, from Hacker News, free and without a key. Everything else the
// curator knows is either an opinion (the judge) or a heuristic (the pre-rank).
//
// Two passes, because the two questions are different:
//   1. exact URL - "was this page submitted"
//   2. title     - "is this story big anywhere"
// Pass 2 is what actually measures virality. The Claude Opus 5 launch thread points
// at anthropic.com, so a URL lookup on a blog's commentary about it returns 0 hits
// while the title lookup finds 1711 points. URL-only matching scored 0.00 for every
// article across two runs - the engagement signal was dead weight.
//
// Candidates that came from the front page already carry their exact score, so they
// are skipped: with hn_top enabled that is a third of the lookups gone.
// --- shared helpers (duplicated per Code node; n8n has no module scope) -------
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const titleTokens = (t) =>
  new Set(
    String(t || '')
      .toLowerCase()
      .replace(/[^a-z0-9 ]/g, ' ')
      .split(/\s+/)
      .filter((w) => w.length > 3 || /\d/.test(w))
      .map((w) => w.replace(/s$/, ''))
  );
const jaccard = (a, b) => {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  return inter / (a.size + b.size - inter);
};
const canonicalHit = (u) =>
  String(u || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[?#].*$/, '')
    .replace(/\/+$/, '');

const cfg = $('parse_curator_config').first().json;
const items = $input.all().map((i) => i.json);

const settle = (j, points, comments, story, match, error) => ({
  json: {
    ...j,
    hn_points: Math.max(num(points, 0), j.source === 'hn' ? num(j.votes, 0) : 0),
    hn_comments: Math.max(num(comments, 0), j.source === 'hn' ? num(j.comments, 0) : 0),
    hn_story_url: story || j.hn_story_url || '',
    hn_match: match,
    hn_error: error || '',
  },
});

if (!cfg.hn_engagement) {
  return items.map((j) => settle(j, j.votes, j.comments, j.hn_story_url, 'disabled', ''));
}

const search = (qs) =>
  this.helpers.httpRequest({
    method: 'GET',
    url: 'https://hn.algolia.com/api/v1/search',
    qs: { tags: 'story', ...qs },
    json: true,
    timeout: 8000,
  });

// Algolia requires every query token to match by default, so a long headline
// returns nothing. Six significant words is enough to identify a story.
const titleQuery = (t) =>
  String(t || '')
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter((w) => w.length > 2)
    .slice(0, 6)
    .join(' ');

// Small worker pool. These calls are independent, so running them one at a time was
// pure wall clock.
const runPool = async (list, worker, concurrency) => {
  const out = new Array(list.length);
  let next = 0;
  await Promise.all(
    Array.from({ length: Math.max(1, Math.min(concurrency, list.length)) }, async () => {
      for (;;) {
        const i = next++;
        if (i >= list.length) return;
        out[i] = await worker(list[i], i);
      }
    })
  );
  return out;
};

const since = Math.floor(Date.now() / 1000) - 14 * 86400;
const startedAt = Date.now();
let errors = 0;
let matched = 0;
let skipped = 0;

const out = await runPool(
  items,
  async (j) => {
    // Already know the exact number, from the front page itself.
    if (j.hn_story_url && num(j.votes, 0) > 0) {
      skipped++;
      matched++;
      return settle(j, j.votes, j.comments, j.hn_story_url, 'source');
    }
    let points = 0;
    let comments = 0;
    let story = '';
    let match = 'none';
    let error = '';
    const take = (h) => {
      if (num(h.points, 0) + num(h.num_comments, 0) <= points + comments) return;
      points = num(h.points, 0);
      comments = num(h.num_comments, 0);
      story = 'https://news.ycombinator.com/item?id=' + h.objectID;
    };
    try {
      // Pass 1: this exact page.
      const byUrl = await search({ query: j.canonical_url, restrictSearchableAttributes: 'url', hitsPerPage: 5 });
      for (const h of (byUrl && byUrl.hits) || []) {
        if (h && h.url && canonicalHit(h.url) === j.canonical_url) {
          match = 'url';
          take(h);
        }
      }
      // Pass 2: the same story, wherever it was submitted. Guarded by title overlap
      // so a generic query cannot borrow an unrelated thread's points.
      if (match === 'none') {
        const mine = titleTokens(j.title);
        const q = titleQuery(j.title);
        // Short titles ("Brute intelligence") cannot be identified reliably by an OR
        // query - two tokens match half of Hacker News. Skip rather than guess.
        if (mine.size >= 3 && q) {
          const byTitle = await search({
            query: q,
            // Algolia ANDs every token by default, so "introducing claude opus" misses
            // a thread titled "Claude Opus 5". optionalWords makes them OR; the
            // overlap guard below is what keeps the result honest.
            optionalWords: q,
            hitsPerPage: 20,
            numericFilters: 'created_at_i>' + since,
          });
          for (const h of (byTitle && byTitle.hits) || []) {
            if (!h) continue;
            if (jaccard(mine, titleTokens(h.title || h.story_title || '')) < 0.4) continue;
            match = 'title';
            take(h);
          }
        }
      }
    } catch (e) {
      errors++;
      error = String((e && e.message) || e).slice(0, 200);
    }
    if (match !== 'none') matched++;
    return settle(j, points, comments, story, match, error);
  },
  cfg.http_concurrency
);

// Surfaced because a blocked egress rule and "nothing is popular today" look
// identical from the digest otherwise.
console.log(
  'fetch_hn_signal: ' + matched + '/' + out.length + ' matched (' + skipped + ' free from hn_top), ' +
    errors + ' request error(s), ' + (Date.now() - startedAt) + 'ms'
);
return out.map((o) => ({ json: { ...o.json, _hn_matched: matched, _hn_lookups: out.length - skipped, _hn_errors: errors } }));

// Choose who gets judged. One LLM call per finalist reads the full article, so this
// is the last free decision in the run and the only place the judge_n budget is set.
//
// Same-story collapse happens here rather than in an LLM call, because the only
// signal that was ever proof is free: two candidates pointing at the same Hacker
// News thread are the same story. The simonwillison and TechCrunch write-ups of
// Opus 5 both resolved to one 1719pt thread. Title overlap already collapsed in
// filter_candidates; this catches the pairs whose headlines share nothing.
const cfg = $('parse_curator_config').first().json;
const items = $input.all().map((i) => i.json).filter((j) => j && j.cid);

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);

// prerank plus the engagement we have now actually measured. Deliberately not a new
// formula: the pre-rank already weighed the free signals against each other, and
// this only lets a story that turned out to be big on Hacker News overtake one that
// merely looked promising.
const withEngagement = items.map((j) => {
  const engagement = clamp(Math.log10(1 + num(j.hn_points, 0) + num(j.hn_comments, 0)) / 2.5, 0, 1);
  return {
    ...j,
    f_engagement: Math.round(engagement * 1000) / 1000,
    rank_score: Math.round((num(j.prerank, 0) + 0.25 * engagement) * 10000) / 10000,
  };
});

const ranked = withEngagement.sort((a, b) => b.rank_score - a.rank_score || a.hours_old - b.hours_old);

const threads = new Map();
const unique = [];
let collapsed = 0;
for (const j of ranked) {
  const t = j.hn_story_url || '';
  if (t && threads.has(t)) {
    collapsed++;
    continue;
  }
  if (t) threads.set(t, j.cid);
  unique.push(j);
}

// Never judge more than the backlog could possibly accept. A judge call is the only
// expensive thing in the run, and admitting is the only thing it buys - so once the
// backlog is full, judging 24 articles to admit zero is pure waste. Yield has run
// around a quarter, so budget four calls per free slot and let judge_n be the ceiling.
// This is what makes running the curator daily cheap: it is a top-up job, and a topped-up
// backlog costs almost nothing.
const bl = cfg.backlog;
const queuedRows = $('read_articles_sheet')
  .all()
  .map((i) => i.json)
  .filter((r) => r && r.URL && String(r.STATUS || '').trim() === 'QUEUE');

const catWeight = (cat) =>
  cfg.category_weights[cat] != null ? cfg.category_weights[cat] : num(cfg.category_weights.default, 0.8);
const byCategory = new Map();
for (const j of unique) {
  if (!byCategory.has(j.category)) byCategory.set(j.category, []);
  byCategory.get(j.category).push(j);
}
const present = [...byCategory.keys()];

// Room is per category, not just global. max_per_category * 5 categories is 50 against a
// max_total of 60, so the per-category cap is what actually binds - and it binds unevenly:
// a run that admitted 3 AI and 1 DevOps fills AI in three runs while Data sits empty.
// After that, allocating by weight alone hands AI its usual ~5 calls per run and
// admit_to_backlog rejects all five with "AI backlog full". So a full category is not
// hungry, and no category is judged more than four calls deep into the room it has left.
const queuedByCat = new Map();
for (const r of queuedRows) {
  const cat = String(r.TOPIC || '').trim() || 'unknown';
  queuedByCat.set(cat, (queuedByCat.get(cat) || 0) + 1);
}
const roomIn = (cat) => Math.max(0, bl.max_per_category - num(queuedByCat.get(cat), 0));
const roomTotal = Math.max(0, bl.max_total - queuedRows.length);
const roomPresent = present.reduce((s, c) => s + (catWeight(c) > 0 ? roomIn(c) : 0), 0);
const room = Math.min(roomTotal, roomPresent);
const budget = Math.max(0, Math.min(cfg.judge_n, room * 4));

// Allocate the judge's queue by category weight, the same rule rank_candidates uses for
// the pool. A flat per-category cap of judge_n/3 let Tech take a third of the calls, and
// the judge blocks consumer tech on sight - those were 6 calls spent to learn nothing.
const takenCids = new Set();
const finalists = [];
const take = (list, limit) => {
  let n = 0;
  for (const j of list || []) {
    if (n >= limit || finalists.length >= budget) break;
    if (takenCids.has(j.cid)) continue;
    takenCids.add(j.cid);
    finalists.push(j);
    n++;
  }
  return n;
};
const remainingIn = (cat) => (byCategory.get(cat) || []).filter((j) => !takenCids.has(j.cid)).length;
const takenIn = (cat) => (byCategory.get(cat) || []).filter((j) => takenCids.has(j.cid)).length;
let guard = 0;
while (finalists.length < budget && guard++ < 20) {
  const hungry = present.filter((c) => catWeight(c) > 0 && remainingIn(c) > 0 && takenIn(c) < roomIn(c) * 4);
  if (!hungry.length) break;
  const slots = budget - finalists.length;
  const w = hungry.reduce((s, c) => s + catWeight(c), 0);
  let progress = 0;
  for (const cat of hungry) {
    if (finalists.length >= budget) break;
    const byWeight = Math.max(1, Math.round((slots * catWeight(cat)) / w));
    progress += take(byCategory.get(cat), Math.min(byWeight, roomIn(cat) * 4 - takenIn(cat)));
  }
  if (!progress) break;
}
// Best-first overall inside the budget, so the loop judges the strongest ones first.
finalists.sort((a, b) => b.rank_score - a.rank_score || a.hours_old - b.hours_old);

const byCat = {};
const byHost = {};
for (const j of unique) {
  byCat[j.category] = (byCat[j.category] || 0) + 1;
  byHost[j.host || '(no host)'] = (byHost[j.host || '(no host)'] || 0) + 1;
}
const finalistsByCat = {};
for (const j of finalists) finalistsByCat[j.category] = (finalistsByCat[j.category] || 0) + 1;

const first = items[0] || {};
const stats = {
  run_at: cfg.run_at,
  considered: items.length,
  capped_out: num(first.capped_out, 0),
  filter_stats: first.filter_stats || {},
  pool_by_category: byCat,
  quota_by_category: first.quota_by_category || {},
  pool_top_hosts: Object.entries(byHost)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 4)
    .map(([h, n]) => h + ' ' + n)
    .join(', '),
  same_story_collapsed: collapsed,
  eligible: unique.length,
  finalists: finalists.length,
  finalists_by_category: finalistsByCat,
  judge_budget: budget,
  judge_budget_capped: budget < cfg.judge_n,
  backlog_room: room,
  backlog_room_full_categories: present.filter((c) => catWeight(c) > 0 && roomIn(c) <= 0),
  hn_matched: num(first._hn_matched, 0),
  hn_lookups: num(first._hn_lookups, 0),
  hn_errors: num(first._hn_errors, 0),
  write_to_sheet: cfg.write_to_sheet,
  mark_read: cfg.mark_read,
};
console.log(
  'pick_finalists ' + JSON.stringify({ eligible: unique.length, collapsed, budget, room: roomTotal, finalists: finalistsByCat })
);

// A full backlog means zero judge calls, which is the point - not an error.
if (finalists.length === 0) return [{ json: { no_selection: true, _stats: stats, _runners_up: [] } }];
return finalists.map((j) => ({ json: { ...j, _stats: stats } }));

// Excerpt-only feed: the judge needs the real article, not two sentences.
const j = $('loop_judge_finalists').first().json;
const dl = $json || {};
const text = String(dl.contentMkdown || dl.content || '').trim();
return [{
  json: {
    ...j,
    judge_content: (text || j.excerpt || '').slice(0, 12000),
    content_source: text ? 'download_content' : 'download_failed',
    ogImageUrl: dl.ogImageUrl || '',
  },
}];

// Miniflux already has the full article, so skip the Download Content fetch.
const j = $('loop_judge_finalists').first().json;
return [{ json: { ...j, judge_content: (j.content_text || j.excerpt || '').slice(0, 12000), content_source: 'miniflux' } }];

// Merge the verdict onto the finalist. There is exactly one article per call now, so
// an unparseable response costs one candidate instead of twenty: the batched triage
// stage this replaced returned a 200 carrying broken JSON on one run and silently
// deleted a whole batch of 20, which retryOnFail never sees because the transport
// succeeded. A failure here scores 0, is flagged, and is named in the digest.
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const HOOKS = ['CONTRARIAN', 'WAR_STORY', 'MISCONCEPTION', 'TRADE_OFF', 'NEWS_REACTION', 'HARD_NUMBER'];

const j = $('loop_judge_finalists').first().json;
const raw = String($json.text || $json.output || '');
let body = raw;
const tagged = raw.match(/<output>([\s\S]*?)<\/output>/i);
if (tagged) body = tagged[1];
body = body.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const s = body.indexOf('{');
const e = body.lastIndexOf('}');
if (s >= 0 && e > s) body = body.slice(s, e + 1);

// Which branch fed the judge - Miniflux's own body or a Download Content fetch -
// only exists on the build_judge_vars_* item, and the loop hands parse_judge the
// pre-judge finalist instead. Read it back from whichever branch ran, guarded by
// cid: the branch that did not run still holds a previous iteration's item, and its
// cid will not match.
const contentSource = (() => {
  for (const name of ['build_judge_vars_downloaded', 'build_judge_vars_local']) {
    try {
      const v = $(name).first().json;
      if (v && v.cid === j.cid) return v.content_source || '';
    } catch (err) {
      /* branch never ran in this execution */
    }
  }
  return j.thin_content ? 'download_unknown' : 'miniflux';
})();

let v = {};
let ok = true;
try {
  v = JSON.parse(body) || {};
  if (typeof v.postability !== 'number') throw new Error('no postability in verdict');
} catch (err) {
  ok = false;
  console.log('WARNING parse_judge: unusable verdict for ' + j.cid + ' (' + j.host + '): ' + String(err.message).slice(0, 140));
}

return [{
  json: {
    ...j,
    postability: ok ? clamp(Math.round(num(v.postability, 0)), 0, 10) : 0,
    judge_blocked: ok ? !!v.blocked : false,
    hook: HOOKS.includes(String(v.hook || '').toUpperCase()) ? String(v.hook).toUpperCase() : '',
    angle: String(v.angle || '').slice(0, 240),
    evidence: String(v.evidence || '').slice(0, 200),
    content_source: contentSource,
    judged: ok,
  },
}];

// Slack digest. It is the whole product while write_to_sheet is false, and the only
// place a silent degradation becomes visible: a dead source, a source that is being
// starved by the pool quotas, a judge call that came back unparseable, a backlog that
// has quietly filled up. Anything that shrinks what reaches the queue gets a line here,
// not just a console.log nobody reads.
const items = $input.all().map((i) => i.json);
const first = items[0] || {};
const stats = first._stats || {};
const noRoom = first._runners_up || [];
const fs = stats.filter_stats || {};
const fmt = (n) => (typeof n === 'number' ? n.toFixed(2) : '-');
const kv = (o) => Object.entries(o || {}).map(([k, n]) => k + ' ' + n).join(' · ');

const lines = [];

if (first.no_selection) {
  if (stats.cleared_floor > 0) {
    lines.push(':package: *Content Feed Curator* - ' + stats.cleared_floor + ' cleared the judge but the backlog had no room.');
  } else {
    lines.push(':warning: *Content Feed Curator* - nothing cleared the judge today.');
  }
} else {
  lines.push(':inbox_tray: *Content Feed Curator* - added ' + items.length + ' to the backlog');
  lines.push('');
  for (const j of items) {
    const f = j.features || {};
    lines.push('*' + j.rank + '. ' + j.TITLE + '*');
    lines.push('<' + j.URL + '|' + j.SOURCE + '>  ·  ' + j.TOPIC + '  ·  score *' + fmt(j.SCORE) + '*  ·  ' + j.PRIORITY);
    lines.push('_' + (j.RATIONALE || 'no evidence returned') + '_');
    if (j.angle) lines.push('*brief:* ' + j.angle);
    const bits = ['post ' + j.postability + '/10', 'topic ' + fmt(f.affinity), 'eng ' + fmt(f.engagement), 'fresh ' + fmt(f.recency)];
    if ((j.topic_hits || []).length) bits.push(j.topic_hits.join(', '));
    if (j.hn_points) bits.push('HN ' + j.hn_points + 'pts/' + j.hn_comments + 'c' + (j.hn_hot ? ' :fire:' : ''));
    if (j.hook) bits.push('hook ' + j.hook);
    if (j.source !== 'miniflux') bits.push('via ' + j.source);
    if ((j.also_from || []).length) bits.push('also on ' + j.also_from.join('/'));
    if (j.content_source === 'download_content') bits.push(':inbox_tray: fetched full text');
    else if (j.content_source === 'download_failed') bits.push(':warning: fetch failed, judged on excerpt');
    else if (j.thin_content) bits.push(':scissors: excerpt only');
    lines.push('`' + bits.join('  |  ') + '`');
    lines.push('');
  }
}

// The backlog is the product now - one row of it gets published per sharing run - so its
// depth per category is the number to read first. A category at 0 will not be publishable
// however good the rest of the run looked.
lines.push(
  '*Backlog* ' + (stats.backlog_before || 0) + ' → ' + (stats.backlog_after || 0) +
    ' of ' + (stats.backlog_max_per_category ? stats.backlog_max_per_category + '/category' : 'cap') +
    '  `' + (kv(stats.backlog_depth) || 'empty') + '`'
);
if (noRoom.length) {
  lines.push('*Cleared the judge, no room*');
  for (const r of noRoom) lines.push('· <' + r.url + '|' + r.title + '> (' + fmt(r.score) + ') - ' + (r.why || ''));
}
lines.push('');

lines.push(
  '`sources: ' + (kv(fs.per_source) || '-') +
    // Hacker News candidates are routed into Data/AI/DevOps by title; one matching no
    // category's keywords is dropped there rather than parked in a category of its own.
    (fs.hn_unrouted ? ' · hn unrouted ' + fs.hn_unrouted : '') +
    ' → ' + (fs.total || 0) + ' raw`'
);
lines.push(
  '`dropped: off-topic ' + (fs.excluded_category || 0) +
    ' · already seen ' + (fs.seen_in_sheet || 0) +
    ' · blocklisted ' + (fs.blocked || 0) +
    ' · same story ' + (fs.merged || 0) +
    ' · short title ' + (fs.no_title || 0) +
    ' · over cap ' + (stats.capped_out || 0) +
    '`'
);
// quota vs filled, always: it is the one line that shows whether a source you added is
// actually reaching the judge. Hacker News contributed 40 candidates and got 1 pool slot
// on the run before quotas existed, and nothing in the digest said so.
lines.push('`quota ' + (kv(stats.quota_by_category) || '-') + '  ->  filled ' + (kv(stats.pool_by_category) || '-') + '`');
lines.push(
  '`pool ' + (stats.considered || 0) +
    ' · collapsed ' + (stats.same_story_collapsed || 0) +
    ' · judged ' + (stats.judged || 0) + '/' + (stats.finalists || 0) +
    (stats.judge_budget_capped ? ' (budget ' + stats.judge_budget + ', room ' + stats.backlog_room + ')' : '') +
    ' · blocked ' + (stats.judge_blocked || 0) +
    ' · unpostable ' + (stats.judge_unpostable || 0) +
    ' · cleared ' + (stats.cleared_floor || 0) +
    ' · admitted ' + (stats.admitted || 0) +
    '`'
);
// Which categories the judge calls are actually buying admissions in. This is the input to
// the category_weights decision - an aggregate block rate cannot tell a bad weight from a
// strict judge.
if ((stats.judge_yield_by_category || []).length) {
  lines.push('`cleared/judged  ' + stats.judge_yield_by_category.join(' · ') + '`');
}
lines.push(
  '`HN ' + (stats.hn_matched || 0) + '/' + (stats.considered || 0) + ' matched, ' + (stats.hn_lookups || 0) + ' lookup(s)' +
    (stats.hn_errors ? ' · :warning: ' + stats.hn_errors + ' request error(s)' : '') +
    '`'
);

// A judge call can return 200 with unparseable JSON, which retryOnFail never sees.
// One call is one article now, so this is a bounded loss - but say it out loud.
if (stats.judge_failed) {
  lines.push(':rotating_light: _' + stats.judge_failed + ' judge verdict(s) came back unusable and scored 0. Check the OpenRouter finish reason._');
}
if ((fs.source_errors || []).length) {
  lines.push(':rotating_light: _Source failure: ' + fs.source_errors.join(' | ') + '_');
}
if (fs.truncated) {
  lines.push(':rotating_light: _Miniflux window truncated - raise `max_entries_per_category`._');
}
// A starving category cannot be published from, and topic rotation on the drain side
// makes that worse rather than better - it will skip to another topic and this one stays
// empty. Name it before the queue runs dry.
const empties = Object.entries(stats.backlog_depth || {}).filter(([, n]) => n === 0).map(([c]) => c);
if (empties.length) lines.push(':warning: _Backlog empty for: ' + empties.join(', ') + '._');
// The mirror image: a full category is skipped by pick_finalists rather than judged and
// rejected, so its candidates go unread. Worth knowing which topic stopped listening.
const full = stats.backlog_room_full_categories || [];
if (full.length) lines.push('_At ' + stats.backlog_max_per_category + '/category and not judged this run: ' + full.join(', ') + '._');
// A TTL under the intake window admits rows that are already dead - judged, admitted,
// expired without ever reaching a slot. The run cannot fix it, so it has to be loud.
if ((stats.ttl_below_floor || []).length) {
  lines.push(
    ':rotating_light: _`ttl_days` below the ' + stats.ttl_floor + '-day floor (`lookback_days` + the longest publish gap): ' +
      stats.ttl_below_floor.join(', ') + '. Rows on those hooks can be admitted already expired._'
  );
}
// Judging costs money; expiring unpublished rows wastes it. The buffer is intended, so
// this only fires once depth is more than double what the publish rate can ever drain.
if (stats.backlog_publishable && stats.backlog_after > stats.backlog_publishable * 2) {
  lines.push(
    ':warning: _Backlog is ' + stats.backlog_after + ' against ~' + stats.backlog_publishable +
      ' that can publish inside a row\'s TTL, at ~' + (stats.judge_cost_per_post || 0) +
      ' judge calls per published post. Lower `max_per_category` if the buffer is not worth that._'
  );
}
if (!stats.write_to_sheet) {
  lines.push('_Dry run: write_to_sheet is false, so nothing was appended and the backlog above is what the sheet already held._');
}

return [{ json: { digest_text: lines.join('\n'), selected: items.length, stats } }];

// Backlog maintenance. The queue is durable now, so this no longer expires every
// unposted AUTO row each run - that was throwing away four judged winners per run to
// publish one. It expires only what should not be published any more:
//
//   1. STALE - past its TTL. Measured from PUBLISHED_AT, the article's own date, not
//      from when we queued it: a launch note is stale ten days after the launch
//      regardless of when it reached the sheet. The TTL comes from the judge's hook,
//      which is the field that already knows whether a piece is perishable -
//      NEWS_REACTION dies in days, a TRADE_OFF or WAR_STORY keeps for weeks. The hook
//      is read back out of the "Hook: X." prefix on EXTRA_PROMPT because content_queue
//      has no HOOK column.
//   2. SURPLUS - over the per-category or global cap, lowest SCORE first. Admission
//      already respects both caps, so this only fires when a cap was lowered in config
//      or rows were added by hand.
//
// ORIGIN=MANUAL is never touched, and neither is anything past QUEUE - IN_PROGRESS,
// WAITING_APPROVAL and PUBLISHED are somebody else's business.
const cfg = $('parse_curator_config').first().json;
const bl = cfg.backlog;
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);

const rows = $('read_articles_sheet').all().map((i) => i.json).filter((r) => r && r.row_number);
const mine = rows.filter(
  (r) => String(r.STATUS || '').trim() === 'QUEUE' && String(r.ORIGIN || '').trim() === 'AUTO'
);

const nowMs = new Date(cfg.run_at).getTime();
const hookOf = (r) => {
  const m = String(r.EXTRA_PROMPT || '').match(/^Hook:\s*([A-Z_]+)\./);
  return m ? m[1] : '';
};
const ttlOf = (r) => {
  const h = hookOf(r);
  // An unknown hook gets the default rather than the short TTL: guessing "perishable"
  // would quietly bin evergreen rows queued before the hook was recorded.
  return num(bl.ttl_days[h], num(bl.ttl_days.default, 21));
};
const ageDaysOf = (r) => {
  const t = Date.parse(r.PUBLISHED_AT || '') || Date.parse(r.UPDATE_DATE || '');
  return isFinite(t) ? (nowMs - t) / 86400000 : 0;
};

const stale = [];
const keep = [];
for (const r of mine) {
  const age = ageDaysOf(r);
  const ttl = ttlOf(r);
  if (age > ttl) stale.push({ r, why: 'stale ' + Math.round(age) + 'd > ' + ttl + 'd (' + (hookOf(r) || 'no hook') + ')' });
  else keep.push(r);
}

// Surplus is measured against what survives plus what is being admitted this run, so
// the two nodes cannot both decide there is room for the same slot.
const incoming = $('admit_to_backlog').all().map((i) => i.json).filter((j) => j && !j.no_selection);
const incomingByCat = new Map();
for (const j of incoming) {
  const c = String(j.TOPIC || '').trim() || 'unknown';
  incomingByCat.set(c, (incomingByCat.get(c) || 0) + 1);
}
// Manual rows occupy the backlog too, so they count towards the caps even though they
// can never be expired by this node.
const manualQueued = rows.filter(
  (r) => String(r.STATUS || '').trim() === 'QUEUE' && String(r.ORIGIN || '').trim() !== 'AUTO'
);

const surplus = [];
const worstFirst = (a, b) => num(Number(a.SCORE), 0) - num(Number(b.SCORE), 0) || b.row_number - a.row_number;

const byCat = new Map();
for (const r of keep) {
  const c = String(r.TOPIC || '').trim() || 'unknown';
  if (!byCat.has(c)) byCat.set(c, []);
  byCat.get(c).push(r);
}
const survivors = new Set(keep.map((r) => r.row_number));
for (const [cat, list] of byCat) {
  const manual = manualQueued.filter((r) => (String(r.TOPIC || '').trim() || 'unknown') === cat).length;
  const room = bl.max_per_category - (incomingByCat.get(cat) || 0) - manual;
  if (list.length <= room) continue;
  for (const r of list.slice().sort(worstFirst).slice(0, list.length - Math.max(0, room))) {
    surplus.push({ r, why: cat + ' over cap ' + bl.max_per_category });
    survivors.delete(r.row_number);
  }
}
// Global backstop, after the per-category pass.
const globalRoom = bl.max_total - incoming.length - manualQueued.length;
const stillHere = keep.filter((r) => survivors.has(r.row_number));
if (stillHere.length > globalRoom) {
  for (const r of stillHere.slice().sort(worstFirst).slice(0, stillHere.length - Math.max(0, globalRoom))) {
    surplus.push({ r, why: 'backlog over ' + bl.max_total });
    survivors.delete(r.row_number);
  }
}

const out = [...stale, ...surplus];
console.log(
  'build_expire_rows: ' + out.length + ' of ' + mine.length + ' AUTO/QUEUE rows expiring (' +
    stale.length + ' stale, ' + surplus.length + ' surplus); ' + survivors.size + ' kept'
);
for (const o of out.slice(0, 10)) console.log('  expire r' + o.r.row_number + ' ' + o.why + ' - ' + String(o.r.TITLE || '').slice(0, 60));

// The Google Sheets update node needs at least one item to not error on an empty input,
// and alwaysOutputData upstream would hand it a junk row. Return nothing and let the
// node be skipped: n8n does not run a node with zero input items.
return out.map((o) => ({ json: { row_number: o.r.row_number, TITLE: o.r.TITLE || '', reason: o.why } }));

// Mark the whole fetched Miniflux window read, not just the candidates that survived
// the cap. 205 entries per run were being dropped by the cap and left unread, so they
// were re-fetched the next run at full cost while only scoring worse on recency.
// Hacker News candidates have no entry_id - there is nothing to mark.
const fetched = $('fetch_candidates')
  .all()
  .map((i) => i.json)
  .filter((j) => j && j.source === 'miniflux' && j.entry_id);
const entryIds = [...new Set(fetched.map((j) => j.entry_id))];
console.log('build_mark_read_payload: marking ' + entryIds.length + ' Miniflux entries read');
if (entryIds.length === 0) return [{ json: { entry_ids: [], status: 'read', skipped: true } }];
return [{ json: { entry_ids: entryIds, status: 'read', skipped: false } }];

// Admission control, not selection. The queue is a durable backlog now, so this node
// does not build a slate of five - it adds whatever cleared the judge, up to whatever
// room the backlog has.
//
// Why: LinkedIn Post Sharing publishes exactly ONE row per run (select_article_to_post
// ends in slice(0, 1)). The old design spent 16 judge calls to produce five options,
// published one, and expired the other four on the next run - then re-fetched and
// re-judged from scratch. Four articles the judge had scored 8+ were thrown away every
// run while the same run reported a short slate. Keeping them costs nothing.
//
// So: no top_n, no per-domain slate cap, no relax ladder. Variety is decided on the way
// OUT, by topic rotation in select_article_to_post, which can guarantee it across a week
// instead of fighting for it inside one slate.
const cfg = $('parse_curator_config').first().json;
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const round = (v, d) => Math.round(v * Math.pow(10, d)) / Math.pow(10, d);
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const canonicalRow = (u) =>
  String(u || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[?#].*$/, '')
    .replace(/\/+$/, '');

const items = $input.all().map((i) => i.json).filter((j) => j && j.cid);
const stats = { ...(($('pick_finalists').first().json || {})._stats || {}) };

// The backlog as it stands, read at the top of the run.
const rows = $('read_articles_sheet').all().map((i) => i.json).filter((r) => r && r.URL);
const queued = rows.filter((r) => String(r.STATUS || '').trim() === 'QUEUE');
// Every URL in the sheet, whatever its STATUS and whatever category it sits under.
// filter_candidates already dropped these upstream; this is the guard that makes the
// per-category backlogs safe to reason about - a link lives in exactly one of them.
const everSeen = new Set(rows.map((r) => canonicalRow(r.URL)));

const backlogByCategory = new Map();
const backlogByHost = new Map();
for (const r of queued) {
  const cat = String(r.TOPIC || '').trim() || 'unknown';
  const host = String(r.SOURCE || '').trim();
  backlogByCategory.set(cat, (backlogByCategory.get(cat) || 0) + 1);
  if (host) backlogByHost.set(host, (backlogByHost.get(host) || 0) + 1);
}

const catWeight = (j) =>
  cfg.category_weights[j.category] != null ? cfg.category_weights[j.category] : num(cfg.category_weights.default, 0.8);

const scored = items.map((j) => {
  const hot = num(j.hn_points, 0) + num(j.hn_comments, 0) >= cfg.hn_hot_points;
  const score = clamp(
    (num(j.postability, 0) / 10) * catWeight(j) + (hot ? cfg.hn_boost : 0) + (j.starred ? cfg.starred_boost : 0),
    0,
    1
  );
  return { ...j, hn_hot: hot, category_weight: catWeight(j), score: round(score, 4) };
});

// postability 0-3 means "nothing to build on", and no amount of attention should
// override that. A viral launch note with a feature list and no numbers scored 0.66
// and reached the queue before this floor existed.
const blocked = scored.filter((j) => j.judge_blocked).length;
const failed = scored.filter((j) => !j.judged).length;
const cleared = scored
  .filter((j) => j.judged && !j.judge_blocked && num(j.postability, 0) >= cfg.min_postability)
  .sort((a, b) => b.score - a.score || a.hours_old - b.hours_old);

const bl = cfg.backlog;
const admitted = [];
const rejected = [];
let totalQueued = queued.length;
const seenThisRun = new Set();

for (const j of cleared) {
  const cat = j.category || 'unknown';
  const host = j.host || '';
  const key = canonicalRow(j.url);
  let why = '';
  if (everSeen.has(key) || seenThisRun.has(key)) why = 'already in the sheet';
  else if (totalQueued >= bl.max_total) why = 'backlog full (' + bl.max_total + ')';
  else if ((backlogByCategory.get(cat) || 0) >= bl.max_per_category) why = cat + ' backlog full (' + bl.max_per_category + ')';
  else if (host && (backlogByHost.get(host) || 0) >= cfg.max_per_host) why = host + ' at ' + cfg.max_per_host + ' in backlog';

  if (why) {
    rejected.push({ title: j.title, host: j.host, score: j.score, url: j.url, why });
    continue;
  }
  seenThisRun.add(key);
  backlogByCategory.set(cat, (backlogByCategory.get(cat) || 0) + 1);
  if (host) backlogByHost.set(host, (backlogByHost.get(host) || 0) + 1);
  totalQueued++;
  admitted.push(j);
}

const bands = cfg.priority_bands;
const priorityOf = (s) => (s >= bands.VERY_HIGH ? 'VERY_HIGH' : s >= bands.HIGH ? 'HIGH' : s >= bands.MEDIUM ? 'MEDIUM' : 'LOW');

const depth = {};
for (const [cat, n] of backlogByCategory) depth[cat] = n;
stats.judged = items.filter((j) => j.judged).length;
stats.judge_failed = failed;
stats.judge_blocked = blocked;
stats.judge_unpostable = scored.length - blocked - failed - cleared.length;
stats.cleared_floor = cleared.length;
stats.admitted = admitted.length;
stats.no_room = rejected.length;
stats.backlog_before = queued.length;
stats.backlog_after = totalQueued;
stats.backlog_depth = depth;
stats.backlog_max_per_category = bl.max_per_category;
// Yield PER CATEGORY, because the aggregate "blocked 13 of 23" cannot answer the only
// question worth asking about category_weights: is a category's weight wrong, or is the
// judge just strict? Tech sits at 0.65 and is documented as rarely postable, but nothing
// in the digest has ever shown whether Tech actually blocks harder than AI - so the
// decision to zero it, the way News is zeroed, has never had data behind it. One run is
// noise; three runs of this line is an answer.
const yieldByCat = {};
for (const j of scored) {
  const c = j.category || 'unknown';
  if (!yieldByCat[c]) yieldByCat[c] = { n: 0, ok: 0 };
  yieldByCat[c].n++;
  if (j.judged && !j.judge_blocked && num(j.postability, 0) >= cfg.min_postability) yieldByCat[c].ok++;
}
stats.judge_yield_by_category = Object.entries(yieldByCat)
  .sort((a, b) => b[1].n - a[1].n)
  .map(([c, v]) => c + ' ' + v.ok + '/' + v.n);
// How many rows can actually reach LinkedIn before the TTL bins them: the publish rate
// times the default TTL. Depth beyond this is reserve, and reserve costs judge calls.
stats.backlog_publishable = Math.ceil((cfg.publish_per_week * num(bl.ttl_days.default, 21)) / 7);
// A TTL shorter than the intake window admits rows that are already dead. NEWS_REACTION
// was 4 days against a lookback of 5, so an article at the edge of the window was judged,
// admitted and expired without ever reaching a publish slot. The floor is the intake
// window plus the longest gap between slots (Fri -> Mon = 3), so every admitted row gets
// at least one shot. This is a config error the run cannot fix, so it is reported loudly.
stats.ttl_floor = num(cfg.lookback_days, 5) + 3;
stats.ttl_below_floor = Object.entries(bl.ttl_days)
  .filter(([, d]) => num(d, 999) < stats.ttl_floor)
  .map(([h, d]) => h + ' ' + d + 'd');
// The honest cost of the buffer: judge calls spent per post that actually goes out. The
// curator and the publisher both run publish_per_week times a week, so one run's judge
// calls is one published post's worth of spend.
stats.judge_cost_per_post = stats.judged;
console.log(
  'admit_to_backlog ' + JSON.stringify({ cleared: cleared.length, admitted: admitted.length, no_room: rejected.length, backlog: totalQueued })
);

// Nothing admitted is a normal outcome now: either the judge found nothing, or the
// backlog is already deep. Those are different states and the digest says which.
if (admitted.length === 0) return [{ json: { no_selection: true, _stats: stats, _runners_up: rejected.slice(0, 5) } }];

return admitted.map((j, i) => ({
  json: {
    rank: i + 1,
    URL: j.url,
    TITLE: j.title,
    STATUS: 'QUEUE',
    PRIORITY: priorityOf(j.score),
    SCORE: j.score,
    ORIGIN: 'AUTO',
    TOPIC: j.category,
    SOURCE: j.host,
    RATIONALE: j.evidence,
    // The angle from the judge is the brief the post generator writes from. The
    // leading "Hook: X." is also how build_expire_rows recovers the hook to pick a
    // TTL, since content_queue has no HOOK column.
    EXTRA_PROMPT: (j.hook ? 'Hook: ' + j.hook + '. ' : '') + (j.angle || ''),
    MAX_WORDS: 300,
    PUBLISHED_AT: j.published_at,
    UPDATE_DATE: cfg.run_at,
    RELEASE_DATE: '',
    LINKEDIN_URL: '',
    // Only Miniflux entries have one, and it is what mark_entries_read needs.
    ENTRY_ID: j.entry_id || '',
    ERROR: '',
    EXECUTION_ID: $execution.id,
    no_selection: false,
    hook: j.hook,
    angle: j.angle,
    source: j.source,
    also_from: j.also_from || [],
    content_source: j.content_source,
    thin_content: j.thin_content,
    postability: j.postability,
    features: {
      postability: round(num(j.postability, 0) / 10, 3),
      affinity: j.f_affinity,
      engagement: j.f_engagement,
      recency: j.f_recency,
      category_weight: j.category_weight,
    },
    topic_hits: j.topic_hits,
    hn_points: j.hn_points,
    hn_comments: j.hn_comments,
    hn_hot: j.hn_hot,
    discussion_url: j.discussion_url,
    ...(i === 0 ? { _stats: stats, _runners_up: rejected.slice(0, 5) } : {}),
  },
}));

// Re-emit the admitted rows, one item per sheet row, immediately before the append.
//
// Why this node exists at all: if_write_to_sheet is four nodes downstream of
// admit_to_backlog, and everything between them collapses the stream to a single item -
// build_digest returns one digest, notify_digest replaces it with Slack's API response.
// So append_content_queue was receiving {ok, channel, message: {...}} and every
// ={{ $json.URL }} mapping resolved to undefined. It appended one blank row per run and
// reported success, because an append of undefined values is not an error.
//
// n8n has no way to "go back" to an earlier node's items in a mapping - a node reference in
// an expression reads ONE item, not the list - so restoring the stream needs a code node.
// This is the standard shape for it: read the named node, re-emit.
//
// Only the 18 sheet columns are emitted. admit_to_backlog's items also carry _stats,
// features, topic_hits and the rest, which the append does not map and nobody downstream
// reads; dropping them here keeps what reaches Google Sheets equal to what the header says.
const COLUMNS = [
  'URL',
  'TITLE',
  'STATUS',
  'PRIORITY',
  'SCORE',
  'ORIGIN',
  'TOPIC',
  'SOURCE',
  'RATIONALE',
  'EXTRA_PROMPT',
  'MAX_WORDS',
  'PUBLISHED_AT',
  'UPDATE_DATE',
  'RELEASE_DATE',
  'LINKEDIN_URL',
  'ENTRY_ID',
  'ERROR',
  'EXECUTION_ID',
];

// admit_to_backlog emits a single { no_selection: true } item when nothing cleared the
// judge or the backlog had no room. That is a normal outcome, not a row - if it reached the
// append it would be the blank-row bug again, wearing a different hat.
const rows = $('admit_to_backlog')
  .all()
  .map((i) => i.json)
  .filter((j) => j && j.no_selection !== true && j.URL);

console.log('build_queue_rows: ' + rows.length + ' row(s) to append');

return rows.map((r) => {
  const out = {};
  for (const c of COLUMNS) out[c] = r[c] != null ? r[c] : '';
  return { json: out };
});
